INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Başkalarına ait fikirlerin, verilerin veya eserlerin, kaynak gösterilmeden sanki kendi eseriymiş gibi sunulmasına ne ad verilir?', 'Fabrication (Uydurma)', 'Falsification (Çarpıtma)', 'Plagiarism (İntihal)', 'Duplication (Tekrar Yayım)', 'C', 'r', 'etik', 'easy', 'İntihal (aşırma), akademik dürüstlüğe aykırı en temel ihlaldir ve başkasının emeğini kaynak göstermeden sahiplenmek demektir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir araştırmada, katılımcıların ''Görüşme'' (Mülakat) tekniği ile derinlemesine duygu ve düşüncelerinin alındığı, sayısal verilerden çok sözel verilerin analiz edildiği araştırma türü hangisidir?', 'Nicel (Quantitative) Araştırma', 'Nitel (Qualitative) Araştırma', 'Deneysel Araştırma', 'Korelasyonel Araştırma', 'B', 'r', 'arastirma_yontemleri', 'easy', 'Nitel araştırmalar ''Neden?'' ve ''Nasıl?'' sorularına odaklanarak olguları kendi ortamında derinlemesine inceler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir makale veya tezde ''Kaynakça/Referanslar'' listesi hazırlanırken en sık kullanılan, sosyal bilimlerde yaygın format hangisidir?', 'APA (American Psychological Association)', 'IEEE', 'SQL', 'SPSS', 'A', 'r', 'yazim_kurallari', 'easy', 'Sosyal bilimlerde (Eğitim, Psikoloji, Sosyoloji vb.) en yaygın kullanılan atıf ve kaynakça düzenleme stili APA formatıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırmada henüz toplanmamış verileri varmış gibi göstermek veya yapılmamış bir deneyi yapılmış gibi raporlamak hangi etik ihlale girer?', 'Dilimleme (Salami Slicing)', 'Uydurma (Fabrication)', 'Çarpıtma (Falsification)', 'İntihal', 'B', 'r', 'etik', 'medium', 'Uydurma (Fabrication), masa başında hayali veri üretmek ve araştırmayı gerçek dışı beyanlarla oluşturmaktır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Anket soruları hazırlanırken ''Hem ders çalışıyor hem de müzik dinlemekten hoşlanıyor musunuz?'' şeklinde bir soru sormak neden yanlıştır?', 'Soru çok uzundur.', 'Yönlendirici sorudur.', 'Çift önermeli (Double-barreled) sorudur.', 'Açık uçlu sorudur.', 'C', 'r', 'anket_yontemleri', 'medium', 'Tek bir soruda iki farklı konuyu (ders çalışma ve müzik dinleme) sormak, katılımcının hangisine cevap verdiğini belirsizleştirir. Her soru tek bir yargıyı ölçmelidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Literatür taramasının (Literature Review) temel amacı aşağıdakilerden hangisidir?', 'Sayfa sayısını artırmak.', 'Mevcut bilgi birikimini özetleyip araştırmanın hangi boşluğu dolduracağını göstermek.', 'Sadece ünlü yazarlardan alıntı yapmak.', 'Veri analizini gerçekleştirmek.', 'B', 'r', 'literatur', 'medium', 'Literatür taraması, konunun geçmişini, bilinenleri ve bilinmeyenleri ortaya koyarak yapılacak çalışmanın özgün değerini (justification) kanıtlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir çalışmanın sonuçlarının, benzer koşullar altında tekrarlandığında aynı sonuçları verme derecesine ne ad verilir?', 'Geçerlilik (Validity)', 'Güvenilirlik (Reliability)', 'Nesnellik', 'Etik', 'B', 'r', 'arastirma_yontemleri', 'medium', 'Güvenilirlik, ölçme aracının tutarlı ve kararlı sonuçlar vermesidir. (Örn: Bir tartının her seferinde aynı ağırlığı göstermesi).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Metin içi atıf yapılırken (Yılmaz vd., 2023) ifadesindeki ''vd.'' ne anlama gelir?', 'Ve diğerleri (ve arkadaşları)', 'Ve devamı', 'Veri dosyası', 'Ve değerlendirenler', 'A', 'r', 'yazim_kurallari', 'easy', 'Çok yazarlı eserlerde (genelde 3 veya daha fazla), ilk yazarın soyadından sonra ''ve diğerleri'' anlamında ''vd.'' (İngilizce: et al.) kısaltması kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel araştırmalarda, araştırmacının çalışma grubunun içine girerek onlarla birlikte yaşayıp gözlem yaptığı tekniğe ne ad verilir?', 'Anket', 'Katılımlı Gözlem', 'Yapılandırılmış Görüşme', 'Deney', 'B', 'r', 'nitel_arastirma', 'medium', 'Katılımlı gözlemde araştırmacı, ''içeriden biri'' gibi davranarak grubun doğal davranışlarını ve kültürünü anlamaya çalışır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Tek bir büyük araştırmayı, yayın sayısını artırmak amacıyla parçalara bölüp birden fazla makale olarak yayımlamaya ne ad verilir?', 'Duplikasyon', 'Dilimleme (Salami Slicing)', 'Korsan Yayın', 'Hayalet Yazarlık', 'B', 'r', 'etik', 'hard', 'Dilimleme, araştırmanın bütünlüğünü bozarak ''en az yayınlanabilir birim'' mantığıyla etik dışı şekilde yayın sayısını şişirmektir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdakilerden hangisi ''Birincil Kaynak'' (Primary Source) örneğidir?', 'Ders kitabı', 'Ansiklopedi maddesi', 'Özgün bir araştırma makalesi (araştırmacının kendi verileriyle)', 'Literatür derlemesi (Review article)', 'C', 'r', 'literatur', 'medium', 'Birincil kaynaklar, bilginin ilk elden üretildiği (deney raporları, anket sonuçları, özgün makaleler) kaynaklardır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Tez veya makalenin başında yer alan, çalışmanın amacını, yöntemini, bulgularını ve sonucunu 150-250 kelime ile özetleyen kısma ne ad verilir?', 'Giriş (Introduction)', 'Öz (Abstract)', 'Önsöz (Preface)', 'Tartışma (Discussion)', 'B', 'r', 'tez_yazimi', 'easy', 'Öz (Abstract), okuyucunun metnin tamamını okumadan çalışma hakkında genel bilgi edinmesini sağlayan kısa özettir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir görüşmede, araştırmacının önceden hazırladığı soruların dışına çıkabildiği, sohbet tarzında derinleşebildiği görüşme türü hangisidir?', 'Yapılandırılmış Görüşme', 'Yarı Yapılandırılmış Görüşme', 'Anket', 'Kapalı Uçlu Görüşme', 'B', 'r', 'gorusme_teknikleri', 'medium', 'Yarı yapılandırılmış görüşmede ana sorular bellidir ancak araştırmacı duruma göre ek sorular (sondalar) sorarak konuyu derinleştirebilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırmada ''Evren'' (Population) ile ''Örneklem'' (Sample) arasındaki ilişki nedir?', 'Evren, örneklemin küçük bir parçasıdır.', 'Örneklem, evreni temsil etmek üzere seçilen daha küçük bir gruptur.', 'İkisi de aynı şeydir.', 'Evren sadece insanlardan, örneklem nesnelerden oluşur.', 'B', 'r', 'arastirma_yontemleri', 'easy', 'Bütün kitleye ulaşmak zor olduğu için, o kitleyi (evreni) temsil yeteneği olan küçük bir grup (örneklem) üzerinde araştırma yapılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Deney grubuna uygulanan işlemin etkisini ölçmek için, hiçbir işlem yapılmayan veya standart prosedür uygulanan gruba ne ad verilir?', 'Müdahale Grubu', 'Kontrol Grubu', 'Pilot Grup', 'Odak Grup', 'B', 'r', 'arastirma_yontemleri', 'medium', 'Kontrol grubu, bağımsız değişkenin (deneyin) etkisini kıyaslamak için kullanılan referans grubudur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bilimsel bir araştırmada ''Sınırlılıklar'' (Limitations) bölümünde ne yazılmalıdır?', 'Araştırmanın ne kadar mükemmel olduğu.', 'Araştırmacının bütçesi.', 'Araştırmanın kapsamı dışında kalan veya kontrol edilemeyen eksiklikler/zorluklar.', 'Teşekkür metni.', 'C', 'r', 'tez_yazimi', 'medium', 'Sınırlılıklar, örneklem büyüklüğü, zaman, ulaşılabilirlik gibi araştırmanın genellenebilirliğini kısıtlayan faktörlerin dürüstçe açıklandığı bölümdür.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel verilerin analizinde, metin içerisindeki anlamlı bölümlerin etiketlenerek kategoriler oluşturulmasına ne ad verilir?', 'Kodlama (Coding)', 'Regresyon', 'Örnekleme', 'Hipotez Testi', 'A', 'r', 'nitel_arastirma', 'medium', 'Kodlama, ham metin verilerinin (görüşme dökümleri vb.) anlamlı kavramlara ve temalara dönüştürülmesi sürecidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir makalede ''yazarın araştırmaya katkısı olmadığı halde adının yazılması'' hangi etik ihlaldir?', 'Hayalet Yazarlık (Ghost Authorship)', 'Armağan Yazarlık (Gift/Honorary Authorship)', 'İntihal', 'Uydurma', 'B', 'r', 'etik', 'hard', 'Armağan yazarlık, akademik nüfuzu kullanmak veya jest yapmak amacıyla çalışmaya katkısı olmayan kişilerin yazar listesine eklenmesidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Likert tipi bir ölçekte (1: Kesinlikle Katılmıyorum ... 5: Kesinlikle Katılıyorum) toplanan veri hangi ölçüm düzeyindedir?', 'Nominal (Sınıflama)', 'Ordinal (Sıralama)', 'Ratio (Oran)', 'Dichotomous (İkili)', 'B', 'r', 'arastirma_yontemleri', 'medium', 'Likert ölçeği bir sıralama belirtir (Katılıyorum > Katılmıyorum), ancak şıklar arasındaki matematiksel mesafe kesin eşit olmadığı için Ordinal kabul edilir (İstatistiksel analizlerde sıklıkla Eşit Aralıklı gibi de işlem görür).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırma raporunda, başka bir çalışmadan ''doğrudan alıntı'' (blok alıntı) yapılıyorsa ve metin 40 kelimeden uzunsa format nasıl olmalıdır?', 'Tırnak içinde ve italik yazılmalıdır.', 'Tırnak kullanılmadan, soldan girintili ayrı bir blok olarak yazılmalıdır.', 'Dipnot olarak verilmelidir.', 'Kırmızı renk ile yazılmalıdır.', 'B', 'r', 'yazim_kurallari', 'hard', 'APA kurallarına göre 40 kelimeyi aşan doğrudan alıntılar tırnak içine alınmaz, ana metinden ayrılarak soldan girintili (indented) bir blok halinde yazılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Faktör analizi sonucunda elde edilen ''Bartlett Küresellik Testi'' (Bartlett''s Test of Sphericity) anlamlı (p<0.05) çıkarsa bu neyi ifade eder?', 'Değişkenler arasında korelasyon yoktur, faktör analizi yapılamaz.', 'Örneklem büyüklüğü yetersizdir.', 'Korelasyon matrisi birim matris değildir, değişkenler ilişkilidir ve faktör analizi yapılabilir.', 'Veriler normal dağılmamaktadır.', 'C', 'spss', 'faktor_analizi', 'hard', 'Bartlett testi, değişkenlerin birbirleriyle korelasyon gösterip göstermediğini test eder. Anlamlı çıkması, faktör analizi yapmak için verinin uygun (ilişkili) olduğunu gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('One-Way ANOVA testi sonucunda gruplar arasında anlamlı bir fark bulunduğunda, farkın tam olarak hangi gruplar arasında olduğunu belirlemek için hangi işlem yapılır?', 'Post-Hoc Testleri (Tukey, Scheffe vb.)', 'Korelasyon Analizi', 'Regresyon Analizi', 'Faktör Döndürme (Rotation)', 'A', 'spss', 'anova', 'medium', 'ANOVA sadece ''fark var'' der. Farkın kaynağını (örn: Grup A ile Grup C arasında) bulmak için Post-Hoc çoklu karşılaştırma testleri uygulanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Mevcut iki değişkenin toplamını veya ortalamasını alarak yeni bir değişken oluşturmak için hangi menü kullanılır?', 'Data > Aggregate', 'Transform > Compute Variable', 'Analyze > Descriptive Statistics', 'Transform > Recode', 'B', 'spss', 'veri_manipulasyonu', 'easy', 'Matematiksel işlemler (toplama, ortalama, formül yazma) yaparak yeni değişken üretmek için ''Compute Variable'' menüsü kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Analiz çıktılarını (Output) kategorik bir değişkene göre (örn: Kadınlar ve Erkekler için ayrı ayrı tablolar halinde) almak için hangi işlem yapılmalıdır?', 'Data > Select Cases', 'Data > Split File', 'Data > Sort Cases', 'Data > Merge Files', 'B', 'spss', 'veri_manipulasyonu', 'medium', 'Split File komutu, veri setini belirtilen değişkene göre gruplara ayırır ve sonraki analizleri her grup için ayrı ayrı raporlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Elinizde ham veri yerine frekans tablosu (özetlenmiş veri) varsa, bu frekansları SPSS''e tanıtmak için hangi komut kullanılır?', 'Data > Weight Cases', 'Data > Select Cases', 'Transform > Count Values', 'Analyze > Frequencies', 'A', 'spss', 'veri_girisi', 'hard', 'Özetlenmiş verilerde, frekans sütununu ''ağırlık'' (weight) olarak tanımlamak için ''Weight Cases'' kullanılır, böylece SPSS o satırın kaç kez tekrar ettiğini anlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Ki-Kare (Chi-Square) analizinde, beklenen değeri (expected count) 5''ten küçük olan hücre sayısı %20''yi aşarsa ne yapılmalıdır?', 'Analiz aynen raporlanır.', 'Fisher''s Exact Test sonucu dikkate alınır veya kategoriler birleştirilir.', 'T-Testi uygulanır.', 'Veri setinden bu gözlemler silinir.', 'B', 'spss', 'varsayimlar', 'hard', 'Ki-Kare testinin temel varsayımlarından biri beklenen değerlerin yeterli büyüklükte olmasıdır. Bu varsayım ihlal edilirse Fisher''s Exact Test veya ''Likelihood Ratio'' kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Normal dağılım gösteren verilerde, verilerin ne kadarının ortalamadan uzaklaştığını gösteren ölçü hangisidir?', 'Medyan', 'Mod', 'Standart Sapma', 'Korelasyon Katsayısı', 'C', 'spss', 'descriptive', 'easy', 'Standart sapma, verilerin aritmetik ortalamadan ne kadar saptığının (yayılımının) bir ölçüsüdür.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Zaman serisi içeren veya aynı deneklerin üç farklı zamanda ölçüldüğü bir deneyde, ortalamaları karşılaştırmak için hangi test kullanılır?', 'One-Way ANOVA', 'Repeated Measures ANOVA', 'Independent Samples T-Test', 'Factor Analysis', 'B', 'spss', 'anova', 'medium', 'Aynı katılımcılardan ikiden fazla kez ölçüm alındığında (tekrarlı ölçümler), gruplar bağımlı olduğu için Repeated Measures ANOVA kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İkili (Binary) Lojistik Regresyon analizinde bağımlı değişkenin yapısı nasıl olmalıdır?', 'Sürekli (Scale) değişken (örn: Puan)', 'İki kategorili (Dichotomous) değişken (örn: Hasta/Sağlam)', 'Sıralı (Ordinal) değişken (örn: Eğitim seviyesi)', 'Tarih değişkeni', 'B', 'spss', 'regresyon', 'hard', 'Binary Logistic Regression, bağımlı değişkenin sadece iki kategoriye (0 ve 1 gibi) sahip olduğu durumlarda kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İki kategorik değişkenin frekans dağılımlarını bir tablo halinde görmek (örn: Cinsiyete göre Sigara içme durumu) için hangi analiz seçilir?', 'Descriptives', 'Crosstabs (Çapraz Tablo)', 'Correlate', 'Explore', 'B', 'spss', 'descriptive', 'easy', 'Crosstabs, iki veya daha fazla kategorik değişkenin kesişimindeki frekansları ve yüzdeleri gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Farklı dosyalardaki aynı kişilere ait farklı değişkenleri tek bir dosyada birleştirmek için hangi komut kullanılır?', 'Data > Merge Files > Add Cases', 'Data > Merge Files > Add Variables', 'Data > Transpose', 'Data > Split File', 'B', 'spss', 'veri_yonetimi', 'medium', 'Aynı ID''ye sahip kişilerin yeni verilerini (yeni sütunlar) eklemek için ''Add Variables'' kullanılır. ''Add Cases'' ise yeni kişiler (satırlar) eklemek içindir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Veri setindeki her bir değerin standartlaştırılmış (Z-score) halini yeni bir değişken olarak kaydetmek için en pratik yol hangisidir?', 'Compute Variable ile formül yazmak', 'Analyze > Descriptive Statistics > Descriptives (Save standardized values as variables)', 'Analyze > Compare Means', 'Transform > Recode', 'B', 'spss', 'veri_manipulasyonu', 'medium', 'Descriptives menüsündeki ''Save standardized values...'' kutucuğu işaretlenirse, SPSS otomatik olarak Z puanlarını hesaplayıp veri setine ekler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Verilerin normal dağılıp dağılmadığını görsel olarak incelemek için ''Histogram'' üzerine eklenen eğriye ne ad verilir?', 'Regression Line', 'Normal Curve', 'Bar Line', 'Scatter Line', 'B', 'spss', 'grafikler', 'easy', 'Histogram üzerine eklenen ''Normal Curve'' (Normal Dağılım Eğrisi), verinin çan eğrisine ne kadar uyduğunu gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Biri sıralı (ordinal), diğeri sürekli (scale) olan veya her ikisi de sıralı olan iki değişken arasındaki ilişkiyi incelemek için hangi korelasyon katsayısı tercih edilir?', 'Pearson', 'Spearman''s rho', 'Eta', 'Cronbach Alpha', 'B', 'spss', 'korelasyon', 'medium', 'Veriler normal dağılmıyorsa veya sıralı (ordinal) ölçekteyse Pearson yerine Spearman sıra farkları korelasyon katsayısı kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Sürekli bir değişkeni, belirli kesme noktalarına göre otomatik olarak kategorik hale getirmek (görsel olarak sürükle-bırak yöntemiyle) için hangi araç kullanılır?', 'Transform > Visual Binning', 'Transform > Compute', 'Data > Define Variable Properties', 'Analyze > Classify', 'A', 'spss', 'veri_manipulasyonu', 'medium', 'Visual Binning, histogram üzerinde kesme noktalarını görerek sürekli değişkenleri gruplandırmayı (binning) sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Anketi cevaplamayan veya boş bırakılan soruları analiz dışı bırakmak için Variable View ekranında hangi sütun ayarlanmalıdır?', 'Values', 'Missing', 'Label', 'Role', 'B', 'spss', 'veri_girisi', 'easy', 'Missing sütunu, kullanıcı tanımlı kayıp verilerin (örn: -99 = Cevapsız) SPSS tarafından analiz dışı bırakılmasını sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Normal dağılım analizinde ''Skewness'' (Çarpıklık) değerinin 0 olması neyi ifade eder?', 'Dağılımın sağa çarpık olduğunu', 'Dağılımın sola çarpık olduğunu', 'Dağılımın tam simetrik olduğunu', 'Verinin hatalı olduğunu', 'C', 'spss', 'varsayimlar', 'medium', 'Skewness değerinin 0 olması, dağılımın sağa veya sola yatık olmadığını, tam simetrik (normal) olduğunu gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Parametrik olmayan testlerden ''Kruskal-Wallis H Testi'', parametrik testlerden hangisinin alternatifidir?', 'Independent Samples T-Test', 'Paired Samples T-Test', 'One-Way ANOVA', 'Pearson Correlation', 'C', 'spss', 'non_parametric', 'hard', 'Üç veya daha fazla bağımsız grubun karşılaştırılmasında, normallik varsayımı sağlanamıyorsa One-Way ANOVA yerine Kruskal-Wallis H testi kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bağımlı iki grup (Önce-Sonra) karşılaştırmasında parametrik varsayımlar sağlanamıyorsa, Paired Samples T-Test yerine hangi test kullanılır?', 'Mann-Whitney U', 'Wilcoxon Signed Rank Test', 'Chi-Square', 'Kruskal-Wallis', 'B', 'spss', 'non_parametric', 'hard', 'Bağımlı (eşleştirilmiş) gruplar için parametrik olmayan test Wilcoxon İşaretli Sıralar Testidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir regresyon analizinde ''Durbin-Watson'' katsayısı hangi varsayımı test etmek için kullanılır?', 'Normallik (Normality)', 'Otokorelasyon (Autocorrelation)', 'Çoklu Bağlantı (Multicollinearity)', 'Homojenlik (Homogeneity)', 'B', 'spss', 'regresyon', 'hard', 'Durbin-Watson testi, regresyon analizinde hata terimlerinin (residuals) birbirinden bağımsız olup olmadığını (otokorelasyon) test eder. 2''ye yakın olması istenir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Zor ulaşılan veya gizli kalan gruplarla (örn: madde bağımlıları) çalışırken, bir katılımcının referansıyla diğerine ulaşılan örnekleme yöntemi hangisidir?', 'Basit Tesadüfi Örnekleme', 'Tabakalı Örnekleme', 'Kartopu (Snowball) Örnekleme', 'Sistematik Örnekleme', 'C', 'r', 'arastirma_yontemleri', 'medium', 'Kartopu örnekleme, zincirleme bir şekilde katılımcıların birbirini önermesiyle örneklemin büyüdüğü, ulaşılması zor kitleler için ideal bir yöntemdir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir deneyde, araştırmacının manipüle ettiği (değiştirdiği) ve sonuca etkisini incelediği değişken türü hangisidir?', 'Bağımlı Değişken', 'Bağımsız Değişken', 'Kontrol Değişkeni', 'Karıştırıcı Değişken', 'B', 'r', 'arastirma_yontemleri', 'easy', 'Bağımsız değişken ''neden'' konumundadır; araştırmacı tarafından değiştirilir. Bağımlı değişken ise bu değişimden etkilenen ''sonuç''tur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırma sonuçlarının, örneklemden daha büyük bir kitleye (evrene) genellenebilme derecesine ne ad verilir?', 'İç Geçerlilik', 'Dış Geçerlilik', 'Yapı Geçerliliği', 'Güvenilirlik', 'B', 'r', 'arastirma_yontemleri', 'medium', 'Dış geçerlilik, elde edilen bulguların laboratuvar veya çalışma grubu dışındaki gerçek dünyaya ne kadar aktarılabileceği ile ilgilidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Katılımcıların araştırmaya katılmadan önce, araştırmanın amacı, riskleri ve hakları konusunda bilgilendirilip onaylarının alınmasına ne denir?', 'Etik Kurul İzni', 'Gizlilik Sözleşmesi', 'Bilgilendirilmiş Onam (Informed Consent)', 'Debriefing', 'C', 'r', 'etik', 'easy', 'Bilgilendirilmiş onam, araştırma etiğinin temelidir; katılımcının neye dahil olduğunu bilerek gönüllü katılımını sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İstatistiksel analizlerde ''Gruplar arasında fark yoktur'' veya ''Değişkenler arasında ilişki yoktur'' önermesine dayanan hipotez türü hangisidir?', 'Alternatif Hipotez (H1)', 'Araştırma Hipotezi', 'Sıfır/Yokluk Hipotezi (H0)', 'Yönlü Hipotez', 'C', 'r', 'arastirma_yontemleri', 'medium', 'H0 (Null Hypothesis), aksi kanıtlanana kadar durumun değişmediğini veya fark olmadığını varsayan, test edilen temel hipotezdir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('6-10 kişilik bir grubun, bir moderatör eşliğinde belirli bir konu hakkında tartıştığı nitel veri toplama tekniği hangisidir?', 'Derinlemesine Görüşme', 'Odak Grup Görüşmesi (Focus Group)', 'Vaka Analizi', 'Anket', 'B', 'r', 'nitel_arastirma', 'easy', 'Odak grup görüşmeleri, grup dinamiğini kullanarak katılımcıların fikirlerini, tutumlarını ve etkileşimlerini anlamayı hedefler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Dijital ortamdaki makalelere kalıcı erişim sağlamak için verilen ve ''https://doi.org/...'' ile başlayan benzersiz kodun adı nedir?', 'ISBN', 'ISSN', 'DOI (Digital Object Identifier)', 'URL', 'C', 'r', 'literatur', 'easy', 'DOI, dijital nesneleri etiketlemek için kullanılan kalıcı bir kimlik numarasıdır; web adresi değişse bile dokümana ulaşmayı sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Yazarın daha önce yayınlanmış kendi eserinden, kaynak göstermeden büyük bloklar halinde alıntı yapıp yeni bir eser gibi sunmasına ne ad verilir?', 'Kendinden İntihal (Self-Plagiarism)', 'Korsanlık', 'Hayalet Yazarlık', 'Atıf Yapma', 'A', 'r', 'etik', 'medium', 'Kişinin kendi eseri olsa bile, eski çalışmasını yeniymiş gibi sunması veya kaynak göstermemesi akademik dürüstlüğe aykırıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Hem nicel (sayısal) hem de nitel (sözel) yöntemlerin aynı araştırmada birlikte kullanılmasına ne ad verilir?', 'Deneysel Yöntem', 'Karma Yöntem (Mixed Methods)', 'Korelasyonel Yöntem', 'Etnografik Yöntem', 'B', 'r', 'arastirma_yontemleri', 'medium', 'Karma yöntemler, araştırma problemine daha geniş bir bakış açısı getirmek için nicel verilerin genellenebilirliği ile nitel verilerin derinliğini birleştirir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Asıl araştırmaya başlamadan önce, ölçme araçlarını test etmek ve olası sorunları görmek için küçük bir grupla yapılan ön çalışmaya ne denir?', 'Son Test', 'Pilot Uygulama (Pilot Study)', 'Meta Analiz', 'Alan Taraması', 'B', 'r', 'arastirma_yontemleri', 'easy', 'Pilot çalışma, ana araştırmanın ''provası'' niteliğindedir; anket sorularının anlaşılırlığını ve süreci test etmeyi sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir olayı, kişiyi veya kurumu kendi doğal çerçevesi içinde derinlemesine ve çok yönlü inceleyen araştırma deseni hangisidir?', 'Tarama Modeli', 'Durum Çalışması (Case Study)', 'Deneysel Model', 'Meta Analiz', 'B', 'r', 'nitel_arastirma', 'medium', 'Durum çalışması (vaka incelemesi), sınırları belirli bir sistemin (bir okul, bir hasta, bir şirket) detaylı analizidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Tezin ''Tartışma'' (Discussion) bölümünde aşağıdakilerden hangisinin yapılması BEKLENMEZ?', 'Bulguların literatürdeki diğer çalışmalarla kıyaslanması.', 'Bulguların ne anlama geldiğinin yorumlanması.', 'Daha önce bahsedilmeyen tamamen yeni istatistiksel bulguların ilk kez sunulması.', 'Araştırmanın sınırlılıklarından bahsedilmesi.', 'C', 'r', 'tez_yazimi', 'hard', 'Tartışma bölümü yorumlama yeridir; yeni veriler ve bulgular ''Bulgular'' bölümünde sunulmalıdır. Tartışma''da sürpriz yeni veri verilmez.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Evrenin alt gruplara (örn: Cinsiyet, Yaş) ayrıldığı ve her gruptan evrendeki oranına göre rastgele seçim yapıldığı örnekleme türü hangisidir?', 'Basit Tesadüfi Örnekleme', 'Tabakalı (Stratified) Örnekleme', 'Amaçsal Örnekleme', 'Gelişigüzel Örnekleme', 'B', 'r', 'arastirma_yontemleri', 'medium', 'Tabakalı örnekleme, alt grupların (örneğin %60 Kadın, %40 Erkek) örneklemde de aynı oranda temsil edilmesini garanti altına alır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırmada geçerliliği artırmak için birden fazla veri toplama aracı, birden fazla araştırmacı veya birden fazla yöntemin kullanılmasına ne ad verilir?', 'Çeşitleme / Üçgenleme (Triangulation)', 'Korelasyon', 'Standartlaştırma', 'Rastgeleleştirme', 'A', 'r', 'arastirma_yontemleri', 'hard', 'Çeşitleme (Triangulation), aynı olguyu farklı açılardan inceleyerek önyargıyı azaltmak ve sonuçların doğruluğunu teyit etmek için kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bilimsel bir makalenin yayımlanmadan önce, o alandaki uzmanlar tarafından isimsiz olarak incelenip onaylanması sürecine ne ad verilir?', 'Editör Kontrolü', 'Akran/Hakem Değerlendirmesi (Peer Review)', 'İntihal Taraması', 'Etik Kurul', 'B', 'r', 'yazim_kurallari', 'medium', 'Peer review, bilimsel kalitenin korunması için makalenin konunun uzmanları (hakemler) tarafından körleme usulüyle denetlenmesidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aynı örneklem grubunun uzun yıllar boyunca izlendiği ve verilerin belirli aralıklarla tekrar toplandığı araştırma türü hangisidir?', 'Kesitsel (Cross-sectional) Araştırma', 'Boylamsal (Longitudinal) Araştırma', 'Tarihsel Araştırma', 'Vaka Çalışması', 'B', 'r', 'arastirma_yontemleri', 'medium', 'Boylamsal araştırmalar, değişimi ve gelişimi zaman içinde görmek için (örneğin 10 yıl boyunca her yıl ölçüm yaparak) kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Tez veya raporun sonuna eklenen; anket formları, izin belgeleri, ek tablolar gibi materyallerin bulunduğu bölüme ne ad verilir?', 'Kaynakça', 'Ekler (Appendices)', 'Dizin', 'Önsöz', 'B', 'r', 'tez_yazimi', 'easy', 'Metin akışını bozacak kadar detaylı veya hacimli belgeler (ölçek izinleri, ham veri tabloları vb.) ''Ekler'' bölümünde sunulur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Genel teorilerden veya hipotezlerden yola çıkarak özel durumları test eden (Genelden özele) akıl yürütme yöntemi hangisidir?', 'Tümevarım (Induction)', 'Tümdengelim (Deduction)', 'Analoji', 'Betimleme', 'B', 'r', 'arastirma_yontemleri', 'hard', 'Nicel araştırmaların temeli olan tümdengelim, mevcut teoriyi doğrulamak veya yanlışlamak için veriyi kullanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir makalede kullanılan ''İkincil Veri'' (Secondary Data) neyi ifade eder?', 'Araştırmacının bizzat topladığı verileri.', 'Başka bir araştırmacı veya kurum tarafından daha önce toplanmış verileri (TÜİK verileri gibi).', 'Yedek verileri.', 'Güvenilir olmayan verileri.', 'B', 'r', 'arastirma_yontemleri', 'easy', 'İkincil veri, araştırmacının kendisinin toplamadığı, hali hazırda var olan veri setleri (nüfus sayımı, hasta kayıtları vb.) üzerinde çalışmasıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('APA formatına göre kaynakçada ''Kitap'' künyesi yazılırken hangi bilgi İTALİK yazılır?', 'Yazarın soyadı', 'Yayınevi', 'Kitabın adı', 'Basım yılı', 'C', 'r', 'yazim_kurallari', 'medium', 'APA stilinde kitapların ve dergilerin (makale değil, derginin kendisi) isimleri italik yazılır. Örn: Soyadı, A. (2020). *Kitabın Adı*. Yayınevi.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir regresyon modelinde ''Adjusted R Square'' (Düzeltilmiş R Kare) değeri neden R Square yerine tercih edilir?', 'Daha yüksek bir değer verdiği için', 'Modele eklenen gereksiz değişkenler için ceza puanı uygulayarak daha gerçekçi bir açıklayıcılık sunduğu için', 'Sadece küçük örneklemlerde hesaplanabildiği için', 'Negatif değer alabildiği için', 'B', 'spss', 'regresyon', 'medium', 'Normal R Kare, modele değişken eklendikçe sürekli artma eğilimindedir. Düzeltilmiş R Kare ise modele katkısı olmayan değişkenler eklendiğinde düşer, bu yüzden model kıyaslamasında daha güvenilirdir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Üç veya daha fazla bağımlı grubun (tekrarlı ölçümlerin) karşılaştırılmasında kullanılan parametrik olmayan test hangisidir?', 'Kruskal-Wallis Test', 'Friedman Test', 'Mann-Whitney U Test', 'Wilcoxon Signed Rank Test', 'B', 'spss', 'non_parametric', 'hard', 'Repeated Measures ANOVA''nın parametrik olmayan karşılığı Friedman testidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te ''Partial Correlation'' (Kısmi Korelasyon) analizi ne işe yarar?', 'Eksik verileri tamamlayarak korelasyon hesaplar.', 'İki değişken arasındaki ilişkiyi, üçüncü bir değişkenin etkisini kontrol altında tutarak (sabitleyerek) inceler.', 'Sadece pozitif korelasyonları gösterir.', 'Değişkenleri kategorik hale getirir.', 'B', 'spss', 'korelasyon', 'medium', 'Örneğin; dondurma satışı ile boğulma vakaları arasındaki ilişkide ''sıcaklık'' değişkeninin etkisini arındırmak için Kısmi Korelasyon kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Çoklu regresyon analizinde, aykırı değerlerin (Multivariate Outliers) tespiti için hangi istatistik kullanılır?', 'Cronbach''s Alpha', 'Mahalanobis Distance', 'Tukey''s HSD', 'Levene Statistic', 'B', 'spss', 'varsayimlar', 'hard', 'Mahalanobis uzaklığı, çok değişkenli analizlerde bir gözlemin merkezden (ortalamalar vektöründen) ne kadar uzak olduğunu gösterir ve çok değişkenli aykırı değerleri bulmak için kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('ANCOVA (Analysis of Covariance) testinin ANOVA''dan temel farkı nedir?', 'Daha fazla grup karşılaştırabilmesidir.', 'Bağımlı değişkene etki eden bir ''ortak değişkeni'' (covariate) kontrol altına alarak grup farklarına bakmasıdır.', 'Sadece parametrik olmayan verilerde kullanılmasıdır.', 'Post-Hoc testlerine ihtiyaç duymamasıdır.', 'B', 'spss', 'anova', 'hard', 'ANCOVA, bağımlı değişken üzerinde etkisi olabilecek sürekli bir dış değişkenin (covariate) etkisini istatistiksel olarak gidererek grupları karşılaştırır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS veri setinde aynı kişinin birden fazla kez girildiği ''Mükerrer Kayıtları'' (Duplicate Cases) bulmak için hangi menü kullanılır?', 'Data > Identify Duplicate Cases', 'Data > Sort Cases', 'Analyze > Descriptive Statistics', 'Transform > Compute Variable', 'A', 'spss', 'veri_yonetimi', 'easy', 'Veri temizleme aşamasında, aynı ID veya özelliklere sahip tekrar eden satırları tespit etmek için ''Identify Duplicate Cases'' kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir hipotez testinde ''Type I Error'' (Tip 1 Hata) neyi ifade eder?', 'H0 doğru olduğu halde H0''ı reddetmek (Yanlış pozitif).', 'H0 yanlış olduğu halde H0''ı kabul etmek (Yanlış negatif).', 'Veri setinin hatalı girilmesi.', 'Analizin yarıda kesilmesi.', 'A', 'spss', 'hipotez_testleri', 'medium', 'Tip 1 hata, gerçekte bir fark veya ilişki yokken (H0 doğruyken), varmış gibi (H0 red) sonuç bulmaktır. Alpha düzeyi (0.05) bu hatayı yapma riskidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS Syntax''ında bir veri setini açmak için kullanılan komut hangisidir?', 'OPEN DATA', 'GET FILE', 'READ FILE', 'IMPORT DATA', 'B', 'spss', 'syntax', 'medium', 'SPSS''in kendi formatındaki (.sav) dosyaları açmak için kullanılan temel syntax komutu ''GET FILE''dır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Kategorik bir değişkeni (örn: Eğitim Durumu) regresyon analizine sokabilmek için ''Dummy Coding'' (Kukla Değişken Kodlaması) yapıldığında, k kategorili bir değişken için kaç adet dummy değişken oluşturulur?', 'k kadar', 'k - 1 kadar', 'k + 1 kadar', 'k / 2 kadar', 'B', 'spss', 'regresyon', 'hard', 'Dummy kodlamada bir kategori referans alınır, bu yüzden k kategorili bir değişken için k-1 adet yeni (0-1) değişken oluşturulur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Effect Size (Etki Büyüklüğü) hesaplamasında kullanılan ''Cohen''s d'' değeri 0.8 ve üzeri ise etki nasıldır?', 'İhmal edilebilir', 'Küçük etki', 'Orta etki', 'Geniş (Büyük) etki', 'D', 'spss', 'descriptive', 'medium', 'Cohen''s d için genel kabul gören sınırlar: 0.2 küçük, 0.5 orta, 0.8 ve üzeri büyük etkidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Verilerin homoscedasticity (eş varyanslılık) varsayımını ihlal etmesi, regresyon analizinde hangi grafikte belli olur?', 'Histogram', 'Scatterplot (Residuals vs Predicted Values)', 'Boxplot', 'Pie Chart', 'B', 'spss', 'varsayimlar', 'hard', 'Hata terimlerinin (residuals) tahmin edilen değerlere göre dağılım grafiğinde (Scatterplot) huni şeklinde bir görüntü oluşması, varyansların homojen olmadığını (Heteroscedasticity) gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te çıktı (Output) dosyasının uzantısı nedir?', '.sav', '.spv', '.sps', '.csv', 'B', 'spss', 'dosya_yapisi', 'easy', '.sav veri dosyası, .sps syntax dosyası, .spv ise analiz sonuçlarının olduğu çıktı dosyasıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Non-parametrik testlerde ''Medyan'' değerleri karşılaştırılırken, parametrik testlerde ne karşılaştırılır?', 'Mod', 'Aralık (Range)', 'Ortalama (Mean)', 'Varyans', 'C', 'spss', 't_testleri', 'easy', 'Parametrik testler (t-testi, ANOVA vb.) ortalamalar üzerinden işlem yaparken, parametrik olmayan testler sıra puanları ve medyanlar üzerinden ilerler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdaki korelasyon katsayılarından hangisi ''belirleme katsayısı'' (Coefficient of Determination) olarak adlandırılır?', 'r', 'r kare (r²)', 'p değeri', 't değeri', 'B', 'spss', 'korelasyon', 'medium', 'Korelasyon katsayısının karesi (r²), bir değişkendeki varyansın ne kadarının diğer değişken tarafından açıklandığını gösterir ve belirleme katsayısı olarak adlandırılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te değişken isimleri (Variable Name) verilirken aşağıdakilerden hangisi YAPILAMAZ?', 'İsim rakamla başlatılamaz.', 'Büyük/küçük harf kullanılabilir.', 'Alt çizgi (_) kullanılabilir.', 'İsim 64 karakterden uzun olabilir.', 'A', 'spss', 'veri_girisi', 'easy', 'SPSS''te değişken isimleri harfle başlamalıdır, rakam veya özel karakterlerle ($, # hariç) başlayamaz ve boşluk içeremez.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Kümeleme (Cluster) analizinde, verilerin hangi kümelere atandığını gösteren ''Dendrogram'' grafiği hangi yöntemle elde edilir?', 'K-Means Clustering', 'Hierarchical Clustering', 'Two-Step Clustering', 'Discriminant Analysis', 'B', 'spss', 'ileri_analiz', 'medium', 'Hiyerarşik kümeleme analizi, kümelerin birleşme aşamalarını ağaç yapısı şeklinde gösteren Dendrogram grafiğini üretir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir ölçek geliştirme çalışmasında ''Madde-Toplam Korelasyonu'' (Item-Total Correlation) düşük çıkan bir madde için ne yapılmalıdır?', 'Madde ölçekten çıkarılmalıdır.', 'Maddenin puanı artırılmalıdır.', 'Madde ters kodlanmalıdır.', 'Hiçbir şey yapılmaz.', 'A', 'spss', 'guvenilirlik', 'medium', 'Madde-toplam korelasyonunun düşük olması (genelde <0.30), o maddenin ölçeğin bütünüyle uyumlu olmadığını gösterir ve güvenilirliği artırmak için madde çıkarılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Ki-Kare (Chi-Square) Uyumluluk İyiliği (Goodness of Fit) testi neyi test eder?', 'İki değişken arasındaki ilişkiyi.', 'Gözlenen frekansların, teorik/beklenen frekanslara uyup uymadığını.', 'Ortalamalar arasındaki farkı.', 'Varyansların homojenliğini.', 'B', 'spss', 'non_parametric', 'medium', 'Goodness of Fit testi tek bir kategorik değişken için yapılır ve dağılımın beklenen bir dağılıma (örn: eşit dağılım) uyup uymadığını kontrol eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Standartlaştırılmış Z puanlarının ortalaması ve standart sapması her zaman kaçtır?', 'Ortalama=1, SD=0', 'Ortalama=0, SD=1', 'Ortalama=10, SD=1', 'Ortalama=100, SD=15', 'B', 'spss', 'descriptive', 'easy', 'Z dönüşümü yapıldığında veriler standart normal dağılıma çekilir; bu dağılımın ortalaması 0, varyansı ve standart sapması 1''dir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Hangi analiz türünde bağımsız değişkenler ''Faktör'', bağımlı değişkenler ise ''Bağımlı Değişken'' kutusuna atılır?', 'Korelasyon', 'ANOVA', 'Regresyon', 'Faktör Analizi', 'B', 'spss', 'anova', 'easy', 'SPSS ANOVA arayüzünde grupları belirten kategorik değişkenler ''Factor'' kısmına, ölçülen sayısal değişken ''Dependent List'' kısmına atılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İki kategorik değişkenin (Örn: Seçim öncesi ve sonrası parti tercihi) aynı örneklem üzerindeki değişimini test etmek için kullanılan parametrik olmayan test hangisidir?', 'Chi-Square Independence Test', 'McNemar Test', 'Mann-Whitney U', 'Fisher''s Exact Test', 'B', 'spss', 'non_parametric', 'hard', 'McNemar testi, bağımlı (eşleşmiş) gruplarda kategorik (nominal) verilerin değişimi olup olmadığını test eder (2x2 tablolar için).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te karmaşık grafikleri sürükle-bırak yöntemiyle oluşturmak ve önizlemek için kullanılan menü hangisidir?', 'Graphs > Legacy Dialogs', 'Graphs > Chart Builder', 'Analyze > Descriptive Statistics', 'View > Graphboard', 'B', 'spss', 'grafikler', 'easy', 'Chart Builder, grafik türlerini ve eksenleri görsel olarak düzenleyerek grafik oluşturmayı sağlayan modern arayüzdür.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Güvenilirlik analizinde ''Cronbach''s Alpha if Item Deleted'' sütunu neyi gösterir?', 'Madde silindiğinde kalan maddelerin ortalamasını.', 'İlgili madde ölçekten çıkarılırsa, ölçeğin toplam güvenilirlik katsayısının ne olacağını.', 'Maddenin varyansını.', 'Maddenin diğer maddelerle korelasyonunu.', 'B', 'spss', 'guvenilirlik', 'medium', 'Bu değer, mevcut Alpha değerinden daha yüksekse, o maddenin ölçekten çıkarılması güvenilirliği artırır anlamına gelir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Tekrarlı Ölçümler ANOVA (Repeated Measures ANOVA) analizinde ''Mauchly''s Test of Sphericity'' anlamlı çıkarsa (varsayım ihlal edilirse) hangi düzeltme değerlerine bakılır?', 'Bonferroni & Tukey', 'Greenhouse-Geisser & Huynh-Feldt', 'Levene & Bartlett', 'Pearson & Spearman', 'B', 'spss', 'anova', 'hard', 'Küresellik varsayımı (Sphericity) ihlal edildiğinde serbestlik derecesi düzeltmesi yapan Greenhouse-Geisser veya Huynh-Feldt satırları raporlanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Çoklu regresyon analizinde, modele en çok katkı sağlayan değişkenleri sırasıyla ekleyip anlamsız olanları çıkaran yönteme ne ad verilir?', 'Enter Method', 'Stepwise Method', 'Hierarchical Method', 'Remove Method', 'B', 'spss', 'regresyon', 'medium', 'Stepwise (Adımsal) yöntem, istatistiksel kriterlere göre değişkenleri modele otomatik olarak ekler veya çıkarır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Çoklu karşılaştırmalarda (Post-Hoc), yapılan hata oranını (Type I error) kontrol altında tutmak için en katı (muhafazakar) düzeltmeyi yapan test hangisidir?', 'LSD (Least Significant Difference)', 'Tukey', 'Bonferroni', 'Duncan', 'C', 'spss', 'anova', 'hard', 'Bonferroni düzeltmesi, alpha değerini yapılan test sayısına bölerek (0.05 / k) hatayı en aza indirir ancak fark bulmayı zorlaştırır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Verilerin normal dağılıma uyması için ''Logaritmik Dönüşüm'' (Log Transformation) yapmak istiyorsanız hangi fonksiyonu kullanırsınız?', 'SQRT(variable)', 'LN(variable) veya LG10(variable)', 'ABS(variable)', 'MEAN(variable)', 'B', 'spss', 'veri_manipulasyonu', 'medium', 'Sağa çarpık verileri normale yaklaştırmak için LN (Doğal Logaritma) veya LG10 (10 tabanında logaritma) fonksiyonları Compute Variable menüsünde kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir evren ortalaması ile örneklem ortalaması arasında fark olup olmadığını test etmek (Örn: Sınıfın not ortalaması 50''den farklı mı?) için hangi test kullanılır?', 'Independent Samples T-Test', 'One-Sample T-Test', 'Paired Samples T-Test', 'One-Way ANOVA', 'B', 'spss', 't_testleri', 'easy', 'Tek bir grubun ortalamasını bilinen bir sabit değerle (test değeri) karşılaştırmak için Tek Örneklem (One-Sample) T-Testi kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Faktör analizinde, bir faktörün açıkladığı varyans miktarını gösteren ve genelde 1''den büyük olması beklenen değere ne ad verilir?', 'Factor Loadings', 'Eigenvalue (Özdeğer)', 'Communality', 'Rotated Component Matrix', 'B', 'spss', 'faktor_analizi', 'medium', 'Eigenvalue (Özdeğer), bir faktörün ne kadar bilgi taşıdığını gösterir. Kaiser kriterine göre özdeğeri 1''den büyük olan faktörler analize dahil edilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Faktör sayısına karar verirken kullanılan ve özdeğerlerin grafiğini çizerek ''kırılma noktasını'' gösteren grafik hangisidir?', 'Scatter Plot', 'Scree Plot (Yamaç Grafiği)', 'Boxplot', 'Histogram', 'B', 'spss', 'faktor_analizi', 'medium', 'Scree Plot, faktörlerin özdeğerlerini dikey eksende gösterir; eğimin yataylaştığı nokta faktör sayısını belirlemede ipucu verir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Eksik verilerin (Missing Values) yerine serinin ortalamasının atanması işlemine ne ad verilir?', 'Listwise Deletion', 'Mean Imputation (Ortalama Atama)', 'Pairwise Deletion', 'Regression Imputation', 'B', 'spss', 'veri_yonetimi', 'easy', 'Imputation, eksik verileri doldurma işlemidir. Mean imputation ise eksik gözeneklere o değişkenin genel ortalamasını yazar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Analiz sonucunda elde edilen ''R'' değeri (Korelasyon) 0 ise bu ne anlama gelir?', 'Değişkenler arasında mükemmel bir ilişki vardır.', 'Değişkenler arasında doğrusal bir ilişki yoktur.', 'Negatif bir ilişki vardır.', 'Hata yapılmıştır.', 'B', 'spss', 'korelasyon', 'easy', 'Korelasyon katsayısının 0 olması, iki değişken arasında doğrusal yönde bir ilişkinin bulunmadığını gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS Data View penceresinde satırlar ve sütunlar neyi temsil eder?', 'Satırlar değişkenleri, sütunlar katılımcıları.', 'Satırlar katılımcıları (Cases), sütunlar değişkenleri (Variables).', 'Satırlar analizleri, sütunlar sonuçları.', 'Her ikisi de değişkenleri.', 'B', 'spss', 'arayuz', 'easy', 'SPSS standart veri girişinde her satır bir gözlem birimini (kişi/anket), her sütun ise bir soruyu/özelliği (değişkeni) temsil eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdaki dosya uzantılarından hangisi SPSS Syntax (Kod) dosyasını ifade eder?', '.sav', '.spv', '.sps', '.xml', 'C', 'spss', 'dosya_yapisi', 'easy', '.sps uzantısı, SPSS komutlarının metin tabanlı olarak saklandığı Syntax dosyaları içindir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Normallik testi için örneklem sayısı 50''den büyükse (n > 50) hangi testin sonucuna bakmak daha uygundur?', 'Shapiro-Wilk', 'Kolmogorov-Smirnov', 'Levene', 'Anova', 'B', 'spss', 'varsayimlar', 'medium', 'Genel bir kural olarak, küçük örneklemlerde (<50) Shapiro-Wilk, büyük örneklemlerde (>50) Kolmogorov-Smirnov testi tercih edilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir değişkendeki (örn: Yaş) hatalı girilen uç değerleri (örn: 200) filtreleyip sadece mantıklı aralığı (18-99) görmek için hangi işlem yapılabilir?', 'Data > Select Cases > If condition satisfied', 'Data > Split File', 'Analyze > Correlate', 'Transform > Compute', 'A', 'spss', 'veri_manipulasyonu', 'medium', 'Select Cases menüsünde ''If age >= 18 & age <= 99'' gibi bir koşul yazılarak bu aralık dışındaki veriler analizden geçici olarak çıkarılabilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te çıktıları (Output) Word, Excel veya PDF olarak kaydetmek için hangi menü kullanılır?', 'File > Save As', 'File > Export', 'Edit > Copy Special', 'Data > Export', 'B', 'spss', 'dosya_yapisi', 'easy', 'File > Export menüsü, analiz sonuçlarını .doc, .xls, .pdf gibi yaygın formatlara dönüştürerek dışarı aktarmayı sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Korelasyon analizi yaparken ''korelasyonun neden sonuç ilişkisi belirtmediği'' ilkesi neyi ifade eder?', 'İki değişkenin birlikte değişmesi, birinin diğerine neden olduğu anlamına gelmez.', 'Korelasyon varsa mutlaka nedensellik vardır.', 'Korelasyon sadece negatif olabilir.', 'Regresyon analizi yapılmadan korelasyon hesaplanamaz.', 'A', 'spss', 'korelasyon', 'medium', 'Korelasyon sadece ilişkinin yönünü ve gücünü gösterir; nedensellik (causality) çıkarımı yapmak için deneysel desen veya teorik altyapı gerekir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Doğrusal Regresyon (Linear Regression) analizinin temel varsayımlarından biri olan ''Doğrusallık'' (Linearity) nasıl kontrol edilir?', 'Histogram ile', 'Scatter Plot (Saçılım Grafiği) ile', 'Boxplot ile', 'Bar Chart ile', 'B', 'spss', 'varsayimlar', 'medium', 'Bağımlı ve bağımsız değişken arasındaki ilişkinin doğrusal olup olmadığı en iyi Scatter Plot (Serpilme Diyagramı) ile görselleştirilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir ankette ''Hiç Katılmıyorum (1)'' ile ''Tamamen Katılıyorum (5)'' arasındaki ölçek türü literatürde ne olarak adlandırılır?', 'Likert Ölçeği', 'Guttman Ölçeği', 'Dikotom Ölçek', 'Nominal Ölçek', 'A', 'spss', 'veri_girisi', 'easy', 'Derecelendirme yapılarak görüş belirtilen 5''li veya 7''li ölçek tiplerine Likert tipi ölçek denir ve SPSS''te genellikle Scale (veya Ordinal) olarak tanımlanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te değişkenlerin isimlerini, türlerini, etiketlerini ve ölçüm düzeylerini tanımladığımız pencere hangisidir?', 'Data View', 'Variable View', 'Output View', 'Syntax Editor', 'B', 'spss', 'arayuz', 'easy', 'Variable View (Değişken Görünümü), veri setindeki değişkenlerin özelliklerinin (isim, tip, ölçek vb.) tanımlandığı kısımdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir anketteki ''Cinsiyet'' (Kadın/Erkek) değişkeni SPSS''te hangi ölçüm düzeyi (Measure) ile tanımlanmalıdır?', 'Scale', 'Ordinal', 'Nominal', 'Interval', 'C', 'spss', 'veri_girisi', 'easy', 'Cinsiyet, kategorik bir değişkendir ve kategoriler arasında bir sıralama (büyüklük/küçüklük) olmadığı için Nominal ölçek kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te yapılan bir analiz sonucunda ''Sig.'' (p-value) değeri 0.03 bulunmuştur. Güven düzeyi %95 (alpha=0.05) ise bu sonuç nasıl yorumlanır?', 'H0 hipotezi kabul edilir.', 'Anlamsız bir ilişki vardır.', 'İstatistiksel olarak anlamlı bir fark/ilişki vardır (H0 reddedilir).', 'Test tekrarlanmalıdır.', 'C', 'spss', 'hipotez_testleri', 'medium', 'Sig. (p) değeri 0.05''ten küçük olduğu için (0.03 < 0.05), H0 hipotezi reddedilir ve sonuç istatistiksel olarak anlamlı bulunur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İki bağımsız grubun ortalamaları arasında anlamlı bir fark olup olmadığını test etmek için hangi analiz kullanılır?', 'Paired Samples T-Test', 'One-Way ANOVA', 'Independent Samples T-Test', 'Chi-Square Test', 'C', 'spss', 't_testleri', 'medium', 'İki farklı/bağımsız grubun (örn: Kadınlar ve Erkekler) sayısal bir değişkendeki ortalamalarını karşılaştırmak için Independent Samples T-Test kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Parametrik test varsayımlarının karşılanmadığı durumda, ''Independent Samples T-Test'' yerine kullanılması gereken parametrik olmayan (non-parametric) test hangisidir?', 'Mann-Whitney U Test', 'Wilcoxon Signed Rank Test', 'Kruskal-Wallis H Test', 'Spearman Correlation', 'A', 'spss', 'non_parametric', 'hard', 'Mann-Whitney U testi, iki bağımsız grubun karşılaştırılmasında Independent Samples T-Test''in parametrik olmayan alternatifidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir ölçeğin iç tutarlılığını (güvenilirliğini) ölçmek için SPSS''te en sık kullanılan katsayı hangisidir?', 'Pearson Correlation', 'Cronbach''s Alpha', 'R Square', 'Beta Coefficient', 'B', 'spss', 'guvenilirlik', 'medium', 'Cronbach''s Alpha katsayısı, likert tipi ölçeklerin iç tutarlılığını ve güvenilirliğini ölçmek için kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Üç veya daha fazla bağımsız grubun ortalamalarını karşılaştırmak için kullanılan parametrik test hangisidir?', 'Independent T-Test', 'One-Way ANOVA', 'Manova', 'Regression', 'B', 'spss', 'anova', 'medium', 'Tek Yönlü Varyans Analizi (One-Way ANOVA), üç veya daha fazla grubun ortalamaları arasında fark olup olmadığını test eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Pearson korelasyon katsayısı (r) -0.85 ise, bu iki değişken arasındaki ilişki nasıldır?', 'Zayıf pozitif ilişki', 'Güçlü pozitif ilişki', 'Güçlü negatif ilişki', 'İlişki yoktur', 'C', 'spss', 'korelasyon', 'medium', 'Korelasyon katsayısı -1''e yaklaştıkça negatif ilişki güçlenir. -0.85 güçlü bir negatif ilişkiyi gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te sürekli bir değişkeni kategorik hale getirmek (örneğin: Yaşı, yaş gruplarına çevirmek) için hangi menü kullanılır?', 'Data > Split File', 'Transform > Recode into Different Variables', 'Analyze > Descriptive Statistics', 'Data > Select Cases', 'B', 'spss', 'veri_manipulasyonu', 'medium', 'Mevcut bir değişkeni gruplayarak yeni bir değişkene atamak için ''Recode into Different Variables'' komutu kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Normallik dağılımını test etmek için aşağıdaki testlerden hangileri kullanılır?', 'Kolmogorov-Smirnov & Shapiro-Wilk', 'Levene & Bartlett', 'Tukey & Bonferroni', 'Pearson & Spearman', 'A', 'spss', 'varsayimlar', 'hard', 'Verinin normal dağılıp dağılmadığını test etmek için örneklem büyüklüğüne göre Kolmogorov-Smirnov veya Shapiro-Wilk testleri kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Levene testi sonucunda Sig. değeri 0.01 bulunursa (p < 0.05), bu ne anlama gelir?', 'Varyanslar homojendir.', 'Varyanslar homojen değildir (Farklıdır).', 'Ortalamalar eşittir.', 'Veri normal dağılmaktadır.', 'B', 'spss', 'varsayimlar', 'hard', 'Levene testi varyansların homojenliğini test eder. p < 0.05 ise H0 reddedilir ve varyansların homojen olmadığı (farklı olduğu) kabul edilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Basit doğrusal regresyon analizinde ''R Square'' (R Kare) değeri 0.60 ise bu neyi ifade eder?', 'Bağımlı değişkendeki değişimin %60''ı bağımsız değişken tarafından açıklanmaktadır.', 'Model %40 oranında hatalıdır.', 'Değişkenler arasında %60 korelasyon vardır.', 'Sonuç %60 güvenilirdir.', 'A', 'spss', 'regresyon', 'medium', 'Determinasyon katsayısı (R Kare), bağımsız değişkenin bağımlı değişkeni açıklama yüzdesini belirtir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İki kategorik değişken (örneğin: Eğitim durumu ve Sigara kullanımı) arasında ilişki olup olmadığını test etmek için hangi analiz kullanılır?', 'Pearson Korelasyonu', 'Chi-Square (Ki-Kare) Bağımsızlık Testi', 'T-Testi', 'Faktör Analizi', 'B', 'spss', 'non_parametric', 'medium', 'İki kategorik (nominal veya ordinal) değişken arasındaki ilişkiyi incelemek için Ki-Kare (Chi-Square) testi kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aynı grubun, bir eğitim öncesi ve sonrası başarı puanlarını karşılaştırmak için hangi test uygundur?', 'Independent Samples T-Test', 'Paired Samples T-Test', 'One-Way ANOVA', 'Chi-Square Test', 'B', 'spss', 't_testleri', 'medium', 'Aynı örneklemden elde edilen iki farklı ölçümü (önce-sonra gibi) karşılaştırmak için Bağımlı Örneklem (Paired Samples) T-Testi kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS çıktısında (Output) ''Mean Difference'' neyi ifade eder?', 'Standart sapma farkını', 'Gruplar arası ortalama farkını', 'Varyans farkını', 'Güven aralığını', 'B', 'spss', 'descriptive', 'easy', 'Mean Difference, karşılaştırılan iki durum veya grup arasındaki aritmetik ortalama farkını gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Çoklu regresyon analizinde, bağımsız değişkenler arasında yüksek korelasyon olması durumuna ne ad verilir?', 'Homoscedasticity', 'Autocorrelation', 'Multicollinearity (Çoklu Bağlantı)', 'Normality', 'C', 'spss', 'regresyon', 'hard', 'Çoklu bağlantı (Multicollinearity), bağımsız değişkenlerin birbirleriyle çok yüksek korelasyona sahip olması sorunudur ve modelin güvenilirliğini düşürür.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Veri setini sadece belirli bir kritere uyan (örneğin: sadece Kadınlar) kişilerle analiz etmek için hangi menü kullanılır?', 'Data > Split File', 'Data > Select Cases', 'Data > Weight Cases', 'Transform > Compute Variable', 'B', 'spss', 'veri_manipulasyonu', 'medium', 'Select Cases, analizlerin sadece belirli bir şarta (if condition) uyan gözlemler üzerinde yapılmasını sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aykırı değerleri (Outliers) tespit etmek için en sık kullanılan grafik türü hangisidir?', 'Pie Chart', 'Bar Chart', 'Boxplot (Kutu Grafiği)', 'Histogram', 'C', 'spss', 'grafikler', 'medium', 'Boxplot, verinin çeyrekliklerini gösterir ve kutunun bıyıkları dışında kalan noktalar aykırı değer (outlier) olarak kolayca görülür.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS Syntax editöründe komutların sonuna konulması zorunlu olan işaret hangisidir?', '; (Noktalı virgül)', '. (Nokta)', ', (Virgül)', ': (İki nokta)', 'B', 'spss', 'syntax', 'hard', 'SPSS Syntax dilinde her komut bloğu mutlaka nokta (.) işareti ile bitirilmelidir, aksi takdirde kod çalışmaz.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Kaiser-Meyer-Olkin (KMO) testi hangi analiz öncesinde örneklem yeterliliğini ölçmek için yapılır?', 'Regresyon Analizi', 'Faktör Analizi', 'Kümeleme Analizi', 'T-Testi', 'B', 'spss', 'faktor_analizi', 'hard', 'KMO testi, verinin faktör analizi için uygun olup olmadığını ve örneklem büyüklüğünün yeterliliğini test eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('ANOVA analizinde elde edilen ''Partial Eta Squared'' (Kısmi Eta Kare) değeri neyi ifade eder?', 'Hata oranını.', 'Gruplar arasındaki farkın etki büyüklüğünü (Effect Size).', 'Korelasyon katsayısını.', 'Örneklem büyüklüğünü.', 'B', 'spss', 'anova', 'medium', 'Partial Eta Squared, bağımsız değişkenin bağımlı değişkendeki varyansın ne kadarını açıkladığını gösteren bir etki büyüklüğü ölçüsüdür (0.01 küçük, 0.06 orta, 0.14 büyük etki).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Veri setini ''Geniş Format''tan (Her yıl ayrı sütun) ''Uzun Format''a (Yıllar tek sütun, veriler alt alta) çevirmek için hangi menü kullanılır?', 'Data > Transpose', 'Data > Restructure', 'Data > Split File', 'Transform > Compute', 'B', 'spss', 'veri_yonetimi', 'hard', 'Restructure Data Wizard, tekrarlı ölçümlerin sütunlarda olduğu (Wide) yapıyı, satırlara (Long) çevirmek veya tam tersini yapmak için kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS Syntax penceresinde yazılan bir komutun çalışması için genellikle en sona eklenen ve ''işlemi yürüt'' anlamına gelen komut hangisidir?', 'RUN', 'EXECUTE.', 'COMPUTE', 'GO', 'B', 'spss', 'syntax', 'medium', 'SPSS''te bazı dönüşüm komutları (transformations), ''EXECUTE.'' komutu gelene kadar veya bir prosedür çalıştırılana kadar beklemede (pending) kalır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('2x2''den daha büyük (örn: 3x4) çapraz tablolarda (Crosstabs) kategorik değişkenler arasındaki ilişkinin gücünü ölçmek için hangi katsayı kullanılır?', 'Phi Coefficient', 'Cramer''s V', 'Pearson r', 'Eta', 'B', 'spss', 'korelasyon', 'medium', '2x2 tablolarda Phi katsayısı kullanılırken, daha büyük tablolarda Cramer''s V katsayısı tercih edilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Eksik verilerin rastgele dağılıp dağılmadığını (MCAR - Missing Completely At Random) test etmek için hangi analiz kullanılır?', 'Little''s MCAR Test', 'Levene''s Test', 'Mauchly''s Test', 'Box''s M Test', 'A', 'spss', 'veri_yonetimi', 'hard', 'Little''s MCAR testi, eksik verilerin sistematik bir örüntüye mi sahip olduğunu yoksa tamamen rastgele mi oluştuğunu test eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS çıktısında Sig. (p) değeri ''0.000'' olarak görünüyorsa, akademik raporlamada bu nasıl yazılmalıdır?', 'p = 0.000', 'p < 0.001', 'p = 0', 'p > 0.05', 'B', 'spss', 'raporlama', 'easy', 'İstatistiksel olarak olasılık tam sıfır olamaz. SPSS sadece ilk 3 haneyi gösterir, bu yüzden p < 0.001 (binde birden küçük) şeklinde raporlanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Metin (String) formatında girilmiş kategorik verileri (örn: ''Kadın'', ''Erkek'') otomatik olarak sayısal kodlara (1, 2) dönüştürmek için hangi araç kullanılır?', 'Transform > Automatic Recode', 'Transform > Compute', 'Data > Sort Cases', 'Edit > Replace', 'A', 'spss', 'veri_manipulasyonu', 'easy', 'Automatic Recode, string değişkenleri alfabetik sıraya göre sayısal kodlara dönüştürür ve etiketlerini otomatik atar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Verilerin ortalamadan olan uzaklığını görselleştirmek ve güven aralıklarını göstermek için kullanılan grafik türü hangisidir?', 'Pie Chart', 'Error Bar (Hata Çubukları)', 'Histogram', 'Scatter Dot', 'B', 'spss', 'grafikler', 'medium', 'Error Bar grafikleri, ortalama etrafındaki varyasyonu (Standart Hata veya %95 Güven Aralığı) görselleştirmek için kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Regresyon analizinde ''Normal P-P Plot of Regression Standardized Residuals'' grafiğindeki noktalar köşegen çizgi üzerinde toplanıyorsa bu ne anlama gelir?', 'Hatalar (residuals) normal dağılmaktadır.', 'Model yanlıştır.', 'Doğrusallık varsayımı ihlal edilmiştir.', 'Aykırı değerler vardır.', 'A', 'spss', 'varsayimlar', 'hard', 'Noktaların diyagonal çizgiye yakın seyretmesi, regresyon artıklarının (hatalarının) normal dağılım varsayımını karşıladığını gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bağımsız değişkenlerin, grupları (örn: Kredi verenler vs vermeyenler) ne kadar doğru sınıflandırdığını tahmin etmek için hangi analiz kullanılır?', 'Factor Analysis', 'Discriminant Analysis (Diskriminant Analizi)', 'One-Way ANOVA', 'Pearson Correlation', 'B', 'spss', 'ileri_analiz', 'hard', 'Diskriminant analizi, bağımsız değişkenleri kullanarak bir bağımlı kategorik değişkene (grup üyeliğine) ait olmayı tahminlemeye çalışır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te iki tarih arasındaki gün sayısını (süre) hesaplamak için hangi sihirbaz kullanılır?', 'Transform > Date and Time Wizard', 'Analyze > Time Series', 'Data > Define Dates', 'Transform > Count Values', 'A', 'spss', 'veri_manipulasyonu', 'easy', 'Date and Time Wizard, tarihlerle toplama/çıkarma yapmak veya süre hesaplamak (Duration) için kullanılan hazır bir araçtır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Parametrik varsayımlar sağlanamadığında veya örneklem sayısı çok az olduğunda, güven aralıklarını ve anlamlılığı tahmin etmek için kullanılan simülasyon yöntemi hangisidir?', 'Bootstrapping', 'Forecasting', 'Molding', 'Split-Half', 'A', 'spss', 'ileri_analiz', 'hard', 'Bootstrapping, mevcut veri setinden binlerce kez tekrar örnekleme yaparak (resampling) daha sağlam (robust) istatistiksel tahminler üretir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Veri setindeki tüm vakaların değil, sadece %10''luk rastgele bir kısmının analiz edilmesi için hangi menü kullanılır?', 'Data > Select Cases > Random sample of cases', 'Data > Split File', 'Data > Weight Cases', 'Transform > Random Number Seed', 'A', 'spss', 'veri_yonetimi', 'medium', 'Büyük veri setlerinde pilot analiz yapmak için ''Random sample of cases'' seçeneği ile rastgele bir alt küme seçilebilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdakilerden hangisi bir ''Oran'' (Ratio) ölçeği örneğidir? (Mutlak sıfır noktası olan)', 'Sıcaklık (Santigrat)', 'Aylık Gelir', 'Eğitim Düzeyi', 'Zeka Puanı (IQ)', 'B', 'spss', 'veri_girisi', 'medium', 'Gelir 0 olduğunda para yok demektir (mutlak sıfır). Sıcaklık veya IQ''da 0 değeri, özelliğin yokluğunu göstermez (Interval).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Box''s M testi hangi analizin varsayımını kontrol etmek için kullanılır?', 'MANOVA (Varyans-Kovaryans matrislerinin homojenliği)', 'T-Testi', 'Ki-Kare', 'Korelasyon', 'A', 'spss', 'varsayimlar', 'hard', 'MANOVA''da grupların kovaryans matrislerinin eşit olup olmadığını test etmek için Box''s M testi kullanılır (Anlamsız çıkması istenir, p>0.05).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Güvenilirlik analizinde ''Split-Half'' (Yarıya Bölme) yöntemi ne işe yarar?', 'Ölçeği iki yarıya bölerek iki parça arasındaki tutarlılığı (korelasyonu) inceler.', 'Ölçeği kısaltır.', 'Sadece tek maddelik ölçeklerde kullanılır.', 'Faktör analizi yapar.', 'A', 'spss', 'guvenilirlik', 'medium', 'Split-Half modeli, maddeleri (örneğin tekler ve çiftler olarak) ikiye ayırır ve bu iki yarının birbiriyle tutarlılığını test eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS''te ''Variable View'' sekmesindeki ''Decimals'' sütunu neyi belirler?', 'Verinin ondalık basamak sayısını (görünüm olarak).', 'Verinin maksimum değerini.', 'Verinin sütun genişliğini.', 'Verinin kayıp değer sayısını.', 'A', 'spss', 'veri_girisi', 'easy', 'Decimals, sayısal değerlerin virgülden sonra kaç basamak gösterileceğini ayarlar (Örn: 2 seçilirse 10.00 görünür).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İki sıra (ordinal) değişken arasında çok sayıda eşit değer (ties) varsa, Spearman yerine hangi korelasyon katsayısı tercih edilmelidir?', 'Pearson', 'Kendall''s tau-b', 'Point Biserial', 'Cronbach Alpha', 'B', 'spss', 'korelasyon', 'hard', 'Örneklem küçükse ve sıralamalarda çok fazla çakışma (aynı sırayı paylaşan değerler) varsa Kendall''s tau-b, Spearman''dan daha güvenilir sonuç verir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Outlier analizinde, Z puanı mutlak değer olarak kaçın üzerinde olan veriler genellikle ''aşırı uç değer'' kabul edilir?', '1.0', '1.96', '3.0 (veya 3.29)', '0.05', 'C', 'spss', 'descriptive', 'medium', 'Standart normal dağılımda, ortalamadan ±3 standart sapma (Z=3) uzaklaşan veriler genellikle aykırı değer olarak işaretlenir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('SPSS kısaltmasının (ilk çıkışındaki) orijinal açılımı nedir?', 'Statistical Product and Service Solutions', 'Statistical Package for the Social Sciences', 'System for Probability and Statistical Studies', 'Social Psychology Statistical Software', 'B', 'spss', 'genel_kultur', 'easy', 'IBM satın alıp adını değiştirse de, orijinal ve en bilinen açılımı ''Statistical Package for the Social Sciences''tır (Sosyal Bilimler için İstatistik Paketi).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel araştırmalarda, verilerin toplanması sürecinde yeni bilgi elde edilememeye başlandığı ve tekrarın oluştuğu noktaya ne ad verilir?', 'Kırılma Noktası', 'Doyum Noktası (Saturation)', 'Başlangıç Noktası', 'Aykırı Değer', 'B', 'r', 'nitel_temeller', 'easy', 'Doyum noktası, araştırmacının artık yeni bir kod veya tema bulamadığı, verilerin kendini tekrar etmeye başladığı ve veri toplamanın sonlandırıldığı aşamadır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('NVIVO veya MAXQDA gibi CAQDAS (Bilgisayar Destekli Nitel Veri Analizi) yazılımlarının temel işlevi nedir?', 'Verileri araştırmacı yerine otomatik olarak analiz etmek ve yorumlamak.', 'Verileri organize etmek, kodlamak ve geri çağırmayı kolaylaştırmak.', 'İstatistiksel hipotez testleri yapmak.', 'Anket verilerini SPSS formatına çevirmek.', 'B', 'r', 'yazilim', 'medium', 'Bu yazılımlar analizi araştırmacı adına yapmaz; araştırmacının veriyi düzenlemesine, kodlamasına, görselleştirmesine ve karmaşık sorgular yapmasına yardımcı olan araçlardır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İçerik analizinde, metnin görünen, açık ve doğrudan mesajının analiz edilmesine ne ad verilir?', 'Örtük (Latent) İçerik Analizi', 'Manifest (Görünen) İçerik Analizi', 'Söylem Analizi', 'Betimsel Analiz', 'B', 'r', 'icerik_analizi', 'medium', 'Manifest analiz, metinde doğrudan yer alan kelimeler ve somut kavramlarla ilgilenir (Örn: ''Demokrasi'' kelimesinin kaç kez geçtiği). Örtük analiz ise alt metinle ilgilenir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel araştırmada ''Gömülü Teori'' (Grounded Theory) deseninin temel amacı nedir?', 'Mevcut bir teoriyi test etmek.', 'Verilerden yola çıkarak tümevarım yoluyla yeni bir teori oluşturmak.', 'Kültürel bir grubu tasvir etmek.', 'Değişkenler arası korelasyona bakmak.', 'B', 'r', 'nitel_desenler', 'hard', 'Glaser ve Strauss tarafından geliştirilen Gömülü Teori, önceden belirlenmiş bir hipotezle başlamaz; veriler toplandıkça teori verinin içinden (gömülü olduğu yerden) çıkarılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Katılımcının söylediği ifadenin, hiç değiştirilmeden veya yorumlanmadan doğrudan kod adı olarak kullanılmasına ne denir?', 'Axial Coding (Eksenel Kodlama)', 'In-Vivo Kodlama', 'Selective Coding (Seçici Kodlama)', 'Tematik Kodlama', 'B', 'r', 'kodlama', 'medium', 'In-Vivo kodlama, katılımcının özgün dilini ve kavramlarını korumak için, onların kullandığı kelimeleri doğrudan kod etiketi olarak kullanmaktır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir araştırmacının, araştırma süreci boyunca kendi düşüncelerini, yorumlarını ve metodolojik kararlarını kaydettiği notlara NVIVO/MAXQDA literatüründe ne ad verilir?', 'Node', 'Memo', 'Case', 'Attribute', 'B', 'r', 'yazilim', 'easy', 'Memolar (Analitik notlar), araştırmacının veriyle konuşmasıdır; kodlama yaparken aklına gelen fikirleri ve teorik bağlantıları yazdığı alandır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel araştırmada ''Çeşitleme'' (Triangulation) neyi ifade eder?', 'Sadece üç katılımcı ile görüşme yapılmasını.', 'Araştırma sonuçlarının geçerliliğini artırmak için birden fazla veri kaynağı, yöntem veya araştırmacı kullanılmasını.', 'Verilerin üçgen şeklinde grafiğe dökülmesini.', 'Üç farklı yazılımın aynı anda kullanılmasını.', 'B', 'r', 'nitel_temeller', 'medium', 'Çeşitleme, tek bir yöntemin veya kaynağın yaratabileceği yanlılığı (bias) önlemek için veriyi farklı açılardan doğrulamaktır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('NVIVO''da kodların (temaların) saklandığı ve hiyerarşik olarak düzenlendiği temel birime ne ad verilir?', 'Nodes (Düğümler) / Codes', 'Sources (Kaynaklar)', 'Queries (Sorgular)', 'Classifications', 'A', 'r', 'yazilim', 'easy', 'NVIVO''da bir metin parçasını etiketlediğiniz kutucuklara ''Node'' (yeni sürümlerde Code) denir. Bunlar ''Parent'' ve ''Child'' olarak hiyerarşik dizilebilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdakilerden hangisi Nitel Araştırmanın doğasına uygun bir örnekleme yöntemidir?', 'Basit Tesadüfi Örnekleme', 'Amaçsal (Purposive) Örnekleme', 'Tabakalı Rastgele Örnekleme', 'Küme Örneklemesi', 'B', 'r', 'ornekleme', 'easy', 'Nitel araştırmada amaç temsiliyetten ziyade derinlemesine bilgidir. Bu yüzden zengin bilgi sunacak kişiler özel olarak (amaçsal) seçilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Ses kayıtlarının analize hazır hale gelmesi için metne dökülmesi işlemine ne ad verilir?', 'Kodlama (Coding)', 'Deşifre (Transcription)', 'Kategorizasyon', 'Özetleme', 'B', 'r', 'veri_hazirlama', 'easy', 'Deşifre (Transkripsiyon), görüşme veya odak grup ses kayıtlarının kelimesi kelimesine (verbatim) yazıya geçirilmesi sürecidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İçerik analizinde, birbirleriyle ilişkili kodların bir araya getirilerek oluşturduğu daha üst, soyut kavramlara ne denir?', 'Alıntı', 'Tema (Kategori)', 'Birim', 'Değişken', 'B', 'r', 'icerik_analizi', 'medium', 'Analiz sürecinde: Veri -> Kod -> Kategori/Tema -> Teori/Sonuç hiyerarşisi izlenir. Temalar kodları çatısı altında toplar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('MAXQDA veya NVIVO''da, katılımcıların demografik özelliklerini (Yaş, Cinsiyet, Meslek vb.) tanımlamak için kullanılan özelliklere ne ad verilir?', 'Memos', 'Variables / Attributes (Değişkenler/Öznitelikler)', 'Maps', 'Links', 'B', 'r', 'yazilim', 'hard', 'Bu özellikler sayesinde ''Sadece kadınların bu konudaki görüşlerini getir'' veya ''Gençlerle yaşlıları karşılaştır'' gibi sorgular yapılabilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir kültürün veya grubun davranışlarını, inançlarını ve yaşam biçimini yerinde gözlemleyerek tasvir eden nitel desen hangisidir?', 'Fenomenoloji', 'Etnografi', 'Eylem Araştırması', 'Durum Çalışması', 'B', 'r', 'nitel_desenler', 'medium', 'Etnografi (Kültür tasviri), araştırmacının uzun süre o ortamda yaşayarak kültürü içeriden anlamaya çalıştığı desendir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Kodlayıcılar arası güvenilirlik (Inter-coder reliability) neyi ölçer?', 'Yazılımın hatasız çalışıp çalışmadığını.', 'Farklı araştırmacıların aynı metni bağımsız olarak kodladıklarında ne kadar uyumlu sonuçlara ulaştığını.', 'Katılımcıların doğru söyleyip söylemediğini.', 'Anketin iç tutarlılığını.', 'B', 'r', 'guvenilirlik', 'hard', 'Nitel araştırmada öznelliği azaltmak için, aynı metin iki kişi tarafından kodlanır ve Kappa katsayısı gibi ölçümlerle uyum (güvenilirlik) kontrol edilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Tümdengelim (Deductive) içerik analizi nasıl başlar?', 'Doğrudan veriden kod üretilerek başlar.', 'Önceden belirlenmiş bir teori veya kod listesi ile başlar ve veriler bu listeye göre kodlanır.', 'Rastgele seçimle başlar.', 'Hiçbir ön hazırlık olmadan başlar.', 'B', 'r', 'icerik_analizi', 'medium', 'Tümdengelimci yaklaşımda araştırmacı literatürden veya teoriden hazırladığı bir ''kod defteri'' (codebook) ile veriye yaklaşır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdakilerden hangisi NVIVO/MAXQDA gibi yazılımlarda ''Görselleştirme'' aracı olarak sıkça kullanılır?', 'T-Testi Tablosu', 'Kelime Bulutu (Word Cloud)', 'Regresyon Eğrisi', 'ANOVA Tablosu', 'B', 'r', 'yazilim', 'easy', 'Kelime bulutu, metinde en sık geçen kelimeleri büyüklüklerine göre görselleştirerek araştırmacıya hızlı bir fikir (insight) verir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Fenomenolojik araştırmanın temel odak noktası nedir?', 'Kültürel ritüeller.', 'Bireylerin bir olguya ilişkin yaşanmış deneyimleri (Lived experience) ve bu deneyime yükledikleri anlamlar.', 'Sayısal verilerin genellenebilirliği.', 'Tarihsel belgeler.', 'B', 'r', 'nitel_desenler', 'medium', 'Fenomenoloji, ''Kanser hastası olmak ne anlama gelir?'' veya ''Göçmen olmak nasıl bir histir?'' gibi deneyimlerin özüne iner.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir metin parçasının aynı anda birden fazla koda atanmasına ne denir?', 'Hatalı Kodlama', 'Eşzamanlı (Simultaneous) Kodlama', 'Tekil Kodlama', 'Ayrık Kodlama', 'B', 'r', 'kodlama', 'hard', 'Nitel analizde bir cümle birden fazla anlam taşıyabilir; hem ''ekonomik zorluk'' hem de ''aile içi dayanışma'' koduna aynı anda atanabilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırmacının ve katılımcıların, var olan bir sorunu çözmek için birlikte çalışıp uygulama-yansıtma döngüleri izledikleri desen hangisidir?', 'Eylem Araştırması (Action Research)', 'Biyografi', 'Tarama Modeli', 'Meta Analiz', 'A', 'r', 'nitel_desenler', 'medium', 'Eylem araştırması, sadece durumu anlamayı değil, o durumu değiştirmeyi ve iyileştirmeyi (örn: sınıftaki bir öğrenme sorununu çözmek) hedefler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel verilerin raporlanmasında, araştırmacının yorumlarını desteklemek için en sık başvurduğu kanıt yöntemi nedir?', 'P değerleri', 'Katılımcıların doğrudan alıntıları (Direct Quotes)', 'Pasta Grafikleri', 'Standart Sapma değerleri', 'B', 'r', 'raporlama', 'easy', 'Nitel araştırmanın gücü, katılımcının sesini duyurabilmesindedir. Bu nedenle ''Katılımcı A dedi ki: ...'' şeklindeki alıntılar temel kanıttır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('NVIVO veya MAXQDA''de, farklı gruların (örn: Kadınlar vs Erkekler) belirli temalar hakkında ne sıklıkla konuştuğunu karşılaştırmalı bir tablo olarak görmek için hangi sorgu kullanılır?', 'Word Frequency Query (Kelime Sıklığı Sorgusu)', 'Matrix Coding Query (Matris Kodlama Sorgusu)', 'Text Search Query (Metin Arama Sorgusu)', 'Coding Comparison (Kodlama Karşılaştırma)', 'B', 'r', 'yazilim_ileri', 'hard', 'Matris Kodlama Sorgusu, satırlarda kodların (temaların), sütunlarda ise özniteliklerin (cinsiyet, meslek vb.) yer aldığı ve kesişimdeki frekansları gösteren en güçlü analiz aracıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırmacının kendi geçmiş deneyimlerinin, ön yargılarının ve inançlarının araştırma sürecine etkisini sürekli sorgulaması ve bunu raporlaması sürecine ne ad verilir?', 'Reflexivity (Düşünümsellik / Öz-yansıtma)', 'Triangulation (Çeşitleme)', 'Saturation (Doyum)', 'Sampling (Örnekleme)', 'A', 'r', 'nitel_temeller', 'medium', 'Nitel araştırmada araştırmacı da bir veri toplama aracıdır. Düşünümsellik, araştırmacının sürece olan sübjektif etkisinin farkında olması ve bunu şeffafça paylaşmasıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Gömülü Teori (Grounded Theory) analiz sürecinde kodlama aşamaları sırasıyla nasıldır?', 'Seçici -> Eksenel -> Açık', 'Açık (Open) -> Eksenel (Axial) -> Seçici (Selective)', 'Kapalı -> Açık -> Karma', 'Tematik -> Betimsel -> İstatistiksel', 'B', 'r', 'kodlama', 'hard', 'Önce veriler parçalanır ve etiketlenir (Açık), sonra kategoriler arası ilişkiler kurulur (Eksenel), en son ana çekirdek kategori bulunarak teori oluşturulur (Seçici).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Kelime Bulutu (Word Cloud) oluştururken, ''ve'', ''ile'', ''fakat'', ''bir'' gibi analize anlam katmayan bağlaçların analiz dışı bırakılması işlemine ne ad verilir?', 'Stop Words List (Durdurma Kelimeleri Listesi) oluşturma', 'Lemmatization', 'Autocoding', 'Transkripsiyon', 'A', 'r', 'yazilim', 'easy', 'Stop words listesi, en sık geçen ama içerik açısından anlamsız olan kelimelerin (bağlaçlar, zamirler) frekans sayımından çıkarılmasını sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel araştırmada ''İç Geçerlilik'' (Internal Validity) kavramının karşılığı olarak kullanılan ve sonuçların gerçeği yansıtıp yansıtmadığını ifade eden terim hangisidir?', 'Transferability (Aktarılabilirlik)', 'Credibility (İnandırıcılık)', 'Dependability (Tutarlılık)', 'Confirmability (Teyit Edilebilirlik)', 'B', 'r', 'guvenilirlik', 'medium', 'Lincoln ve Guba''nın kriterlerine göre, nitel araştırmada iç geçerliliğin karşılığı ''İnandırıcılık''tır (Credibility). Yani katılımcıların dünyasının doğru resmedilip resmedilmediğidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Braun ve Clarke (2006) tarafından geliştirilen ve nitel analizde en yaygın kullanılan 6 aşamalı analiz yöntemi hangisidir?', 'Söylem Analizi', 'Tematik Analiz', 'İçerik Analizi', 'Fenomenolojik Analiz', 'B', 'r', 'nitel_desenler', 'medium', 'Veriyi tanıma, kod üretme, temaları arama, temaları gözden geçirme, temaları tanımlama ve raporlama adımlarından oluşan süreç Tematik Analizdir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('NVIVO web tarayıcı eklentisi (NCapture) kullanılarak aşağıdakilerden hangisi veri olarak analiz programına çekilebilir?', 'Sadece Word dosyaları', 'Sosyal medya gönderileri (Twitter/X, Facebook), web sayfaları ve PDF''ler', 'Sadece ses dosyaları', 'SPSS dosyaları', 'B', 'r', 'yazilim', 'medium', 'NCapture, web üzerindeki içerikleri (tweetler, yorumlar, haberler) formatını koruyarak NVIVO''ya aktarmayı sağlayan bir araçtır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Araştırma bulgularının ve yorumların, verileri alınan katılımcılara sunularak ''Sizi doğru anlamış mıyım?'' diye teyit ettirilmesi işlemine ne denir?', 'Peer Debriefing (Akran Değerlendirmesi)', 'Member Checking (Katılımcı Teyidi)', 'External Audit (Dış Denetim)', 'Pilot Çalışma', 'B', 'r', 'guvenilirlik', 'medium', 'Katılımcı teyidi (Member checking), nitel araştırmanın inandırıcılığını artıran en önemli stratejilerden biridir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Metin içindeki ''olumlu'', ''olumsuz'' veya ''nötr'' ifadelerin yazılım tarafından otomatik olarak algılanıp kodlanmasına ne ad verilir?', 'Sentiment Analysis (Duygu Analizi)', 'Discourse Analysis', 'Manual Coding', 'Transcription', 'A', 'r', 'yazilim_ileri', 'medium', 'Modern yazılımlar (NVIVO, MAXQDA), doğal dil işleme teknikleriyle metindeki duygu durumunu otomatik olarak puanlayabilir (Auto-coding sentiment).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Sadece ''ne söylendiğine'' değil, dilin ''nasıl kullanıldığına'', iktidar ilişkilerine ve metnin arkasındaki sosyal yapıya odaklanan analiz türü hangisidir?', 'İçerik Analizi', 'Söylem Analizi (Discourse Analysis)', 'Betimsel Analiz', 'Vaka Analizi', 'B', 'r', 'nitel_desenler', 'hard', 'Söylem analizi, dilin sadece bir iletişim aracı değil, sosyal gerçekliği inşa eden bir araç olduğu kabulüne dayanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('MAXQDA veya NVIVO''da kodlar ve kavramlar arasındaki ilişkileri görselleştirmek için çizilen ağ diyagramlarına ne ad verilir?', 'Frequency Table', 'Concept Map / Project Map (Kavram Haritası)', 'Heatmap', 'Codebook', 'B', 'r', 'yazilim', 'easy', 'Kavram haritaları, teorik model oluştururken değişkenler ve temalar arasındaki nedensellik veya ilişki bağlarını görselleştirmek için kullanılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel bir raporda okuyucunun bağlamı tam olarak anlayabilmesi için ortamın, katılımcıların ve sürecin çok detaylı betimlenmesine Clifford Geertz ne ad vermiştir?', 'Thin Description (Sığ Betimleme)', 'Thick Description (Yoğun Betimleme)', 'Abstract (Özet)', 'Summary', 'B', 'r', 'nitel_temeller', 'hard', 'Yoğun betimleme, bir davranışın sadece fiziksel olarak ne olduğunu değil, o kültür içindeki anlamını ve bağlamını da (örn: göz kırpma vs tik) anlatmaktır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Odak grup görüşmelerinde, ses kaydı dökümünü yaparken konuşmacıları (Speaker 1, Speaker 2...) yazılıma tanıtmanın en büyük faydası nedir?', 'Dosya boyutunu küçültür.', 'Analiz sırasında ''Sadece Ahmet''in söylediklerini getir'' veya ''Kadın konuşmacıları analiz et'' diyebilmeyi sağlar.', 'Otomatik kodlama yapar.', 'Yazım hatalarını düzeltir.', 'B', 'r', 'yazilim', 'medium', 'Odak gruplarda veriyi ''Case'' (Kişi) bazlı sınıflandırmak, grup dinamiklerini ve bireysel katkıları ayrıştırmak için kritiktir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İnsanların yaşadıkları olayları bir hikaye kurgusu (başlangıç-gelişme-sonuç) içinde anlatmalarını inceleyen analiz türü hangisidir?', 'Tematik Analiz', 'Narrative Analysis (Anlatı Analizi)', 'İçerik Analizi', 'SWOT Analizi', 'B', 'r', 'nitel_desenler', 'medium', 'Anlatı analizi, bireylerin kimliklerini ve deneyimlerini hikayeler (narratives) yoluyla nasıl inşa ettiklerine odaklanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Amaçsal örnekleme yöntemlerinden biri olan ve ''birbirinden çok farklı'' katılımcıları seçerek ortak temaları bulmayı hedefleyen yöntem hangisidir?', 'Ölçüt Örnekleme', 'Maksimum Çeşitlilik Örneklemesi (Maximum Variation Sampling)', 'Tipik Durum Örneklemesi', 'Kolayda Örnekleme', 'B', 'r', 'ornekleme', 'medium', 'Maksimum çeşitlilik, heterojen bir gruptaki (örn: farklı yaş, eğitim, şehir) ortak paydaları (pattern) bulmak için kullanılır, bu da bulguların gücünü artırır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('NVIVO''da bir kelimenin metin içinde hangi bağlamda geçtiğini (öncesindeki ve sonrasındaki kelimelerle birlikte) gösteren liste görünümüne ne ad verilir?', 'Word Cloud', 'Word Tree (Kelime Ağacı) / KWIC (Key Word In Context)', 'Matrix', 'Attribute List', 'B', 'r', 'yazilim_ileri', 'medium', 'Kelime ağacı, aranan kelimenin kök olduğu ve ondan dallanan cümlelerin görüldüğü, bağlamı anlamayı sağlayan etkili bir görseldir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Nitel araştırmaların raporlanmasında şeffaflığı artırmak için uluslararası alanda kabul gören kontrol listesi (checklist) hangisidir?', 'CONSORT', 'COREQ (Consolidated Criteria for Reporting Qualitative Research)', 'PRISMA', 'ISO 9001', 'B', 'r', 'raporlama', 'hard', 'COREQ, özellikle mülakat ve odak grup çalışmalarının raporlanmasında nelerin yer alması gerektiğini (araştırmacı özellikleri, çalışma grubu seçimi, analiz vb.) belirleyen standarttır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Analiz yazılımında bir ''Case'' (Vaka) oluşturmak ile bir ''Node/Code'' (Kod) oluşturmak arasındaki temel fark nedir?', 'Fark yoktur.', 'Kodlar tematik (konu) etiketlerdir; Case''ler ise gözlem birimlerini (insanlar, kurumlar) temsil eder ve özellik (yaş, cinsiyet) atanabilir.', 'Kodlar sayısal veridir, Case''ler sözel veridir.', 'Case''ler silinemez.', 'B', 'r', 'yazilim', 'hard', 'Bu ayrım kritiktir. Konuştukları konuları ''Kod''lara, konuşan kişileri ise ''Case''lere atarız ki kişilerin özelliklerine (Attributes) göre karşılaştırma yapabilelim.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdakilerden hangisi bir nitel veri analiz programının (CAQDAS) yapabileceklerinden biri DEĞİLDİR?', 'Büyük veri setlerini organize etmek.', 'Görselleştirmeler (harita, bulut) yapmak.', 'Metindeki kavramları otomatik olarak anlamlandırıp %100 doğru bir teori üretmek.', 'Kodlama frekanslarını saymak.', 'C', 'r', 'yazilim', 'easy', 'Yazılımlar ''anlamlandırma'' yapamaz. İroni, metafor veya derin anlamı çözme ve teoriyi kurma işi tamamen araştırmacının zihinsel emeğine dayalıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Verilerin, kodların veya araştırmacının notlarının (memoların) yazılım dosyası içinde kaybolmaması ve her zaman geri çağrılabilmesi hangi veri tabanı avantajıdır?', 'Manageability (Yönetilebilirlik)', 'Statistical Power', 'Randomness', 'Blindness', 'A', 'r', 'yazilim', 'easy', 'Kağıt-kalem yöntemine göre yazılımların en büyük avantajı, binlerce sayfalık verinin anında erişilebilir, sorgulanabilir ve yönetilebilir (Data Management) olmasıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da verileri görselleştirmek (grafik çizdirmek) için kullanılan en temel ve köklü kütüphane hangisidir?', 'Pandas', 'Matplotlib', 'TensorFlow', 'Numpy', 'B', 'python', 'python', 'easy', 'Matplotlib, Python''daki görselleştirme ekosisteminin atasıdır. Diğer popüler kütüphane Seaborn da Matplotlib üzerine kuruludur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Makine öğrenmesinde, veri setini örneğin 5 eşit parçaya bölüp, her seferinde bir parçayı test, diğerlerini eğitim için kullanarak modelin başarısını doğrulama yöntemine ne denir?', 'Hold-out', 'Cross-Validation (Çapraz Doğrulama)', 'Grid Search', 'Backpropagation', 'B', 'python', 'ml_temel', 'medium', 'K-Fold Cross-Validation, modelin verinin sadece şanslı bir bölümünde iyi çalışıp çalışmadığını anlamak için en güvenilir doğrulama yöntemidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir Karar Ağacı (Decision Tree) algoritması, veriyi dallara ayırırken (splitting) hangi kriteri minimize etmeye çalışır?', 'Learning Rate', 'Entropy (veya Gini Impurity)', 'Accuracy', 'Batch Size', 'B', 'python', 'ml_algoritmalar', 'medium', 'Karar ağaçları, her düğümde veriyi en saf (homojen) hale getirecek soruyu sormak için Entropi veya Gini katsayısını kullanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Pandas DataFrame nesnesindeki sayısal sütunların ortalamasını, standart sapmasını, min/max değerlerini tek komutla özetleyen fonksiyon hangisidir?', 'df.info()', 'df.describe()', 'df.summary()', 'df.stats()', 'B', 'python', 'python', 'easy', '`describe()` fonksiyonu, veri setinin dağılımı hakkında hızlıca fikir sahibi olmak için en pratik yöntemdir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Derin öğrenme modellerinde ''Dropout'' katmanının temel amacı nedir?', 'Eğitimi hızlandırmak.', 'Ağırlıkları sıfırlamak.', 'Rastgele nöronları kapatarak Overfitting''i (Aşırı Öğrenme) engellemek.', 'Veri sayısını artırmak.', 'C', 'python', 'deep_learning', 'medium', 'Dropout, her eğitim adımında nöronların belli bir yüzdesini devre dışı bırakarak ağın belli nöronlara aşırı bağımlı hale gelmesini önler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Dengesiz veri setlerinde (Imbalanced Data - örn: %99 Sağlam, %1 Hasta), modelin başarısını ölçmek için ''Accuracy'' yerine hangi metriklerin kullanılması daha doğrudur?', 'Sadece Accuracy yeterlidir.', 'Precision, Recall ve F1-Score', 'Mean Squared Error', 'R-Squared', 'B', 'python', 'ml_temel', 'medium', 'Dengesiz veride model herkese ''Sağlam'' dese bile %99 Accuracy çıkar ama hatalıdır. F1-Score, hassasiyet ve duyarlılığı birlikte değerlendirir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Birbirine en yakın ''K'' adet komşuya bakarak sınıflandırma yapan (Bana arkadaşını söyle sana kim olduğunu söyleyeyim mantığı) algoritma hangisidir?', 'K-Means', 'KNN (K-Nearest Neighbors)', 'SVM', 'Naive Bayes', 'B', 'python', 'ml_algoritmalar', 'easy', 'KNN, yeni gelen verinin özelliklerine uzayda en yakın olan K adet veriyi bulur ve çoğunluk hangi sınıftaysa onu tahmin eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Zaman serileri, ses veya metin gibi ''sıralı'' (sequential) verilerde geçmiş bilgiyi hatırlayarak işlem yapan Sinir Ağı mimarisi hangisidir?', 'CNN (Convolutional Neural Network)', 'RNN (Recurrent Neural Network)', 'Autoencoder', 'Perceptron', 'B', 'python', 'deep_learning', 'medium', 'RNN''ler (ve geliştirilmiş hali LSTM/GRU), verinin sırasını ve önceki adımlardaki bilgiyi hafızasında tutma yeteneğine sahiptir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Birden fazla Karar Ağacının (Decision Tree) bir araya gelerek oluşturduğu ve genelde tek bir ağaçtan daha başarılı olan ''Topluluk'' (Ensemble) algoritması hangisidir?', 'Linear Regression', 'Random Forest', 'Logistic Regression', 'K-Means', 'B', 'python', 'ml_algoritmalar', 'medium', 'Random Forest, ''Bagging'' yöntemini kullanarak çok sayıda ağaç eğitir ve bunların kararlarının ortalamasını/oy çokluğunu alarak sonucu belirler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Derin öğrenmede, Loss (Hata) fonksiyonunun değerini azaltmak için ağırlıkları güncelleyen optimizasyon algoritmasının genel adı nedir?', 'Gradient Descent (Gradyan İnişi)', 'Standard Scaler', 'Activation Function', 'Cross Validation', 'A', 'python', 'deep_learning', 'hard', 'Gradient Descent, hatanın minimum olduğu noktayı bulmak için parametreleri hatanın türevi (eğimi) yönünde günceller.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Doğal Dil İşleme (NLP) projelerinde, metni kelimelerine veya cümlelerine ayırma işlemine ne ad verilir?', 'Padding', 'Tokenization', 'Embedding', 'Flattening', 'B', 'python', 'nlp', 'easy', 'Tokenization, ham metni analiz edilebilir en küçük parçalara (token) ayırma işlemidir (örn: ''Ali geldi'' -> [''Ali'', ''geldi'']).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Scikit-learn kütüphanesinde veri setini eğitim ve test olarak ayırmak için kullanılan fonksiyon hangisidir?', 'split_data()', 'train_test_split()', 'create_validation()', 'make_split()', 'B', 'python', 'python', 'easy', '`from sklearn.model_selection import train_test_split` komutu makine öğrenmesinin en sık kullanılan başlangıç kodudur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Modelin parametreleri (ağırlıklar) eğitim sırasında öğrenilirken, modelin yapısını yöneten ve eğitimden önce bizim belirlediğimiz parametrelere (örn: Learning Rate, Ağaç Derinliği) ne denir?', 'Weight (Ağırlık)', 'Feature (Özellik)', 'Hyperparameter (Hiperparametre)', 'Bias', 'C', 'python', 'ml_temel', 'medium', 'Hiperparametreler (örn: k-NN''deki K sayısı, Random Forest''taki ağaç sayısı) model tarafından öğrenilmez, veri bilimci tarafından ayarlanır (tuning).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir CNN (Convolutional Neural Network) mimarisinde, görüntü boyutunu küçülterek işlem yükünü azaltan ve önemli özellikleri öne çıkaran katman hangisidir?', 'Convolution Layer', 'Pooling Layer (Ortaklama Katmanı)', 'Dense Layer', 'Output Layer', 'B', 'python', 'deep_learning', 'medium', 'MaxPooling gibi yöntemler, görüntünün (matrisin) boyutunu yarıya indirirken en belirgin özellikleri korur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir ajanın (Agent), çevresiyle etkileşime girip ödül/ceza sistemine göre öğrenerek en yüksek ödülü toplamaya çalıştığı öğrenme türü hangisidir?', 'Supervised Learning', 'Unsupervised Learning', 'Reinforcement Learning (Pekiştirmeli Öğrenme)', 'Deep Learning', 'C', 'python', 'ml_temel', 'medium', 'Satranç oynayan, labirent çözen veya yürümeyi öğrenen robotlar genellikle Pekiştirmeli Öğrenme ile eğitilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da `.npy` uzantılı dosyalar genellikle hangi kütüphane ile oluşturulur ve okunur?', 'Pandas', 'NumPy', 'Matplotlib', 'Scikit-learn', 'B', 'python', 'python', 'easy', 'NumPy, büyük dizileri (arrays) hızlıca kaydetmek ve okumak için kendi ikili (binary) formatı olan .npy''yi kullanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Regresyon probleminde, modelin tahminleri ile gerçek değerler arasındaki ilişkiyi gösteren `R-Squared` (R Kare) değeri en fazla kaç olabilir?', 'Sonsuz', '1.0', '100', '0.5', 'B', 'python', 'ml_temel', 'medium', 'R-Kare, 0 ile 1 arasında değişir. 1.0 (veya %100), modelin verideki değişkenliği mükemmel açıkladığı anlamına gelir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Veri Bilimi projelerinde kod, metin ve görselleştirmeyi aynı anda barındırarak interaktif çalışma sağlayan en popüler ortam hangisidir?', 'Notepad', 'Jupyter Notebook', 'Excel', 'Command Prompt', 'B', 'python', 'python', 'easy', 'Jupyter Notebook (veya Google Colab), hücre yapısı sayesinde kodları parça parça çalıştırmayı ve çıktıları hemen görmeyi sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Makine öğrenmesinde ''Bias'' (Yanlılık) yüksek, ''Variance'' (Varyans) düşük ise modelde ne tür bir sorun vardır?', 'Overfitting (Aşırı Öğrenme)', 'Underfitting (Eksik Öğrenme)', 'Optimal Fitting', 'Data Leakage', 'B', 'python', 'ml_temel', 'hard', 'Bias''ın yüksek olması modelin veriyi öğrenemediğini (çok basit kaldığını), Variance''ın düşük olması ise veri değişimlerine tepki vermediğini gösterir; bu Underfitting''dir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Derin öğrenme modellerini eğitirken, modelin başarısının artık artmadığını görünce eğitimi otomatik olarak durduran yönteme ne denir?', 'Early Stopping', 'Dropout', 'Batch Normalization', 'Grid Search', 'A', 'python', 'deep_learning', 'medium', 'Early Stopping, validation loss değeri belirli bir süre (patience) iyileşmezse, overfitting başlamadan eğitimi keser.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da bir fonksiyon tanımlamak için kullanılan anahtar kelime hangisidir?', 'function', 'func', 'def', 'define', 'C', 'python', 'python', 'easy', 'Python''da fonksiyonlar `def fonksiyon_adi():` yapısı ile tanımlanır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Lojistik Regresyon (Logistic Regression) modelinin çıktısını 0 ile 1 arasına sıkıştırarak ''olasılık'' üretmesini sağlayan fonksiyon hangisidir?', 'ReLU', 'Sigmoid', 'Tanh', 'Linear', 'B', 'python', 'ml_algoritmalar', 'medium', 'Sigmoid fonksiyonu, gelen değerleri ''S'' eğrisi şeklinde bükerek 0 ile 1 arasına dönüştürür, bu da sınıflandırma için idealdir.', true, NOW());
