INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Boyut İndirgeme (Dimensionality Reduction) ve veri görselleştirme amacıyla kullanılan, verideki varyansı en iyi açıklayan bileşenleri bulan gözetimsiz algoritma hangisidir?', 'Linear Regression', 'KNN', 'PCA (Principal Component Analysis)', 'Decision Tree', 'C', 'python', 'ml_temel', 'medium', 'PCA (Temel Bileşenler Analizi), çok boyutlu veriyi (örn: 100 sütun) bilgi kaybını minimumda tutarak daha az boyuta (örn: 2 sütun) indirger.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Büyük veri setleri ve modellerle çalışırken, daha önce büyük bir veri setinde (örn: ImageNet) eğitilmiş bir modelin ağırlıklarını alıp, kendi küçük veri setimize uyarlamaya ne ad verilir?', 'Transfer Learning (Transfer Öğrenme)', 'Reinforcement Learning', 'Unsupervised Learning', 'Scratch Training', 'A', 'python', 'deep_learning', 'easy', 'Transfer öğrenme, tekerleği yeniden icat etmek yerine, başkalarının eğittiği güçlü modellerin (ResNet, BERT vb.) bilgisini kullanmayı sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da tek satırda döngü kurarak liste oluşturmayı sağlayan (örn: `[x**2 for x in range(10)]`) yapıya ne ad verilir?', 'Lambda Function', 'List Comprehension', 'Generator', 'Decorator', 'B', 'python', 'python', 'easy', 'List Comprehension, Python''un en karakteristik ve kod okunabilirliğini artıran pratik özelliklerinden biridir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir sınıflandırma modelinin başarısını ölçen ROC Eğrisinin altında kalan alan (AUC - Area Under Curve) 0.5 ise model hakkında ne söylenebilir?', 'Model mükemmel çalışıyor.', 'Model rastgele tahmin yapıyor (Yazı-tura atmakla aynı).', 'Model %50 hata yapıyor.', 'Veri seti hatalı.', 'B', 'python', 'ml_temel', 'hard', 'AUC değeri 1''e yaklaştıkça model mükemmelleşir. 0.5 değeri, modelin sınıfları ayırt etme yeteneğinin olmadığını (rastgelelik) gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Gradyan İnişi (Gradient Descent) sırasında, modelin her adımda minimum hataya doğru ne kadar büyük bir adım atacağını belirleyen parametre nedir?', 'Batch Size', 'Epoch', 'Learning Rate (Öğrenme Oranı)', 'Dropout Rate', 'C', 'python', 'deep_learning', 'medium', 'Learning Rate çok büyükse model hedefi ıskalar (overshoot), çok küçükse hedefe ulaşması çok uzun sürer.', true, NOW());
