INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Makine öğrenmesinde ''Korelasyon nedensellik (causation) anlamına gelmez'' ifadesi neyi anlatır?', 'İki değişkenin birlikte artması, birinin diğerine sebep olduğu anlamına gelmez.', 'Korelasyon hesaplamak gereksizdir.', 'İlişki varsa mutlaka neden-sonuç bağı vardır.', 'Negatif korelasyon nedenselliktir.', 'A', 'python', 'ml_temel', 'easy', 'Örneğin; yazın dondurma satışı ve boğulma vakaları birlikte artar (pozitif korelasyon), ama dondurma boğulmaya neden olmaz; ortak neden sıcaklıktır.', true, NOW());
