INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir sinir ağında (Neural Network) doğrusal olmayan (non-linear) karmaşık ilişkileri öğrenebilmek için katmanlar arasına ne eklenir?', 'Ağırlık (Weight)', 'Aktivasyon Fonksiyonu (Activation Function)', 'Bias', 'Learning Rate', 'B', 'python', 'deep_learning', 'medium', 'ReLU, Sigmoid veya Tanh gibi aktivasyon fonksiyonları, yapay sinir ağlarına doğrusallığı kırarak karmaşık problemleri çözme yeteneği kazandırır.', true, NOW());
