INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Derin öğrenmede, tüm eğitim veri setinin ağdan bir kez geçip ağırlıkların güncellenmesi sürecine ne ad verilir?', 'Batch', 'Iteration', 'Epoch', 'Layer', 'C', 'python', 'deep_learning', 'medium', '1 Epoch, veri setindeki tüm örneklerin model tarafından bir kez görülmesi demektir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Veri setini ''Eğitim'' (Train) ve ''Test'' olarak ikiye ayırmamızın temel amacı nedir?', 'Veri setini küçültüp hızı artırmak.', 'Modelin görmediği veriler üzerindeki performansını (genelleme yeteneğini) ölçmek.', 'Daha az bellek kullanmak.', 'Overfitting''i artırmak.', 'B', 'python', 'ml_temel', 'easy', 'Modeli eğittiğimiz verilerle test edersek yapay bir başarı elde ederiz. Gerçek performans, modelin hiç görmediği Test setinde belli olur.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Pandas''ta bir DataFrame''in ilk 5 satırını hızlıca görmek için hangi fonksiyon kullanılır?', 'df.show()', 'df.tail()', 'df.head()', 'df.view()', 'C', 'python', 'python', 'easy', 'df.head() varsayılan olarak ilk 5 satırı getirir. İçine sayı yazılarak (örn: df.head(10)) satır sayısı değiştirilebilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Verilerde eksik değerler (NaN / Missing Values) olduğunda, bu değerleri ortalama veya medyan ile doldurma işlemine ne ad verilir?', 'Normalization', 'Imputation', 'One-Hot Encoding', 'Dropout', 'B', 'python', 'ml_temel', 'medium', 'Imputation, eksik verileri silmek yerine istatistiksel yöntemlerle doldurarak veri kaybını önleme tekniğidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Görüntü işleme (Image Processing) ve nesne tanıma görevlerinde en başarılı olan Derin Öğrenme mimarisi hangisidir?', 'RNN (Recurrent Neural Networks)', 'CNN (Convolutional Neural Networks)', 'LSTM', 'Decision Tree', 'B', 'python', 'deep_learning', 'medium', 'CNN''ler (Evrişimli Sinir Ağları), görüntüdeki desenleri, kenarları ve şekilleri algılamak için özelleşmiş katmanlara sahiptir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Regresyon modellerinin başarısını ölçmek için kullanılan metriklerden hangisi ''hataların karesinin ortalamasının karekökü''dür?', 'Accuracy', 'F1 Score', 'RMSE (Root Mean Squared Error)', 'Confusion Matrix', 'C', 'python', 'ml_temel', 'medium', 'RMSE, regresyon hatalarını ölçer ve sonucu hedef değişkenin birimiyle (örn: TL, Metre) aynı ölçekte verir, bu yüzden yorumlaması kolaydır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Kategorik verileri (örn: Renkler: Kırmızı, Mavi) makine öğrenmesi modeline sokabilmek için 0 ve 1''lerden oluşan sütunlara çevirme işlemine ne denir?', 'Standard Scaler', 'Label Encoding', 'One-Hot Encoding', 'Clustering', 'C', 'python', 'python', 'medium', 'One-Hot Encoding, kategorik değişkenleri (özellikle sıralı olmayanları) modelin yanlış bir sıralama algılamaması için ayrı sütunlara (dummy variables) böler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Sinir ağlarında eğitimi hızlandırmak ve hatayı minimize etmek için ağırlıkların güncellenme yönünü belirleyen algoritma/yöntem hangisidir?', 'Forward Propagation', 'Backpropagation (Geri Yayılım)', 'MaxPooling', 'Data Augmentation', 'B', 'python', 'deep_learning', 'hard', 'Backpropagation, çıktıdaki hatayı (loss) geriye doğru yayarak her bir nöronun ağırlığının ne kadar değiştirilmesi gerektiğini hesaplar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Aşağıdaki algoritmalardan hangisi ''Gözetimsiz Öğrenme'' (Unsupervised Learning) örneğidir?', 'Linear Regression', 'Logistic Regression', 'K-Means Clustering', 'Random Forest', 'C', 'python', 'ml_temel', 'medium', 'K-Means, verideki etiketleri bilmeden benzer verileri gruplara (kümelere) ayırır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Pandas''ta `df.iloc` ve `df.loc` arasındaki temel fark nedir?', 'Hiçbir fark yoktur.', 'iloc satır, loc sütun seçer.', 'iloc indeks numarasıyla (integer position), loc etiket ismiyle (label) seçim yapar.', 'loc daha hızlıdır.', 'C', 'python', 'python', 'medium', '`iloc[0]` 0. satırı getirirken, `loc[''Ahmet'']` indeksi ''Ahmet'' olan satırı getirir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Derin öğrenmede, çok büyük veri setlerini modele parça parça vererek RAM/GPU belleğini verimli kullanmayı sağlayan parametre nedir?', 'Epoch Size', 'Batch Size', 'Learning Rate', 'Hidden Layer Size', 'B', 'python', 'deep_learning', 'medium', 'Batch Size, modelin ağırlıklarını güncellemeden önce kaç tane veri örneğini işleyeceğini belirler (Örn: 32, 64).', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Sınıflandırma problemlerinde, modelin ne kadar doğru tahmin yaptığını gösteren; True Positive, False Positive gibi değerleri içeren tabloya ne denir?', 'Scatter Plot', 'Confusion Matrix (Karmaşıklık Matrisi)', 'Correlation Matrix', 'Box Plot', 'B', 'python', 'ml_temel', 'medium', 'Confusion Matrix, modelin hangi sınıfları doğru bildiğini, hangilerini birbiriyle karıştırdığını detaylıca gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Farklı ölçekteki özellikleri (örn: Yaş: 0-100, Maaş: 0-10000) benzer aralığa getirmek için yapılan işleme ne denir?', 'Feature Scaling (Özellik Ölçekleme)', 'Feature Selection', 'Ensembling', 'Hyperparameter Tuning', 'A', 'python', 'ml_temel', 'easy', 'Ölçekleme (Normalization/Standardization), algoritmaların büyük sayısal değerlere sahip değişkenlerden taraflı etkilenmesini önler.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da olası hataları (örn: sıfıra bölme hatası) program çökmeden yakalamak ve yönetmek için kullanılan yapı hangisidir?', 'if - else', 'try - except', 'for - while', 'def - return', 'B', 'python', 'python', 'easy', 'Try bloğu içindeki kodda hata oluşursa program durmaz, kontrol Except bloğuna geçer ve alternatif işlem yapılır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('İki sinir ağının (Biri sahte veri üreten ''Generator'', diğeri sahteyi ayırt eden ''Discriminator'') birbirleriyle yarıştığı derin öğrenme mimarisi hangisidir?', 'CNN', 'RNN', 'GAN (Generative Adversarial Networks)', 'Transformer', 'C', 'python', 'deep_learning', 'hard', 'GAN''lar, gerçekçi insan yüzleri üretmekten sanat eserleri oluşturmaya kadar birçok ''üretken'' (generative) yapay zeka uygulamasının temelidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Modelin aşırı öğrenmesini (Overfitting) engellemek için, hata fonksiyonuna katsayıların büyüklüğüyle orantılı bir ceza terimi ekleme yöntemine ne denir?', 'Normalization', 'Regularization (L1 / L2)', 'Standardization', 'Augmentation', 'B', 'python', 'ml_temel', 'hard', 'L1 (Lasso) ve L2 (Ridge) regülarizasyonu, modelin katsayılarını küçük tutmaya zorlayarak modeli sadeleştirir ve ezberlemeyi zorlaştırır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da Liste (List) ile Demet (Tuple) arasındaki en temel fark nedir?', 'Listeler değiştirilebilir (mutable), demetler değiştirilemez (immutable).', 'Listeler sayı tutamaz.', 'Demetler daha yavaştır.', 'Hiçbir fark yoktur.', 'A', 'python', 'python', 'medium', 'Bir listeye sonradan eleman ekleyip çıkarabilirsiniz, ancak bir Tuple tanımlandıktan sonra içeriği değiştirilemez.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('ChatGPT gibi modern dil modellerinin (LLM) temelini oluşturan ve kelimelerin birbirleriyle ilişkisini ''Attention'' (Dikkat) mekanizmasıyla kuran mimari hangisidir?', 'LSTM', 'Transformer', 'CNN', 'SVM', 'B', 'python', 'deep_learning', 'medium', 'Transformer mimarisi (Google tarafından ''Attention Is All You Need'' makalesiyle tanıtıldı), RNN''lerin yerini alarak NLP alanında devrim yaratmıştır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('K-Means kümeleme algoritmasında, ideal küme sayısını (K) belirlemek için kullanılan ve hata grafiğinin kırılma noktasına bakılan yöntem hangisidir?', 'Elbow Method (Dirsek Yöntemi)', 'Grid Search', 'Random Search', 'Gradient Descent', 'A', 'python', 'ml_algoritmalar', 'medium', 'Grafikte hata (inertia) değerinin düşüşünün yavaşlamaya başladığı dirsek noktası, optimum küme sayısı olarak seçilir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da bir Sınıf (Class) oluşturulduğunda, nesne ilk yaratılırken çalışan ''kurucu'' (constructor) metod hangisidir?', '__main__', '__init__', '__str__', '__class__', 'B', 'python', 'python', 'medium', '`def __init__(self):` metodu, bir sınıftan nesne türetildiğinde otomatik olarak çalışır ve başlangıç özelliklerini atar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Çok derin sinir ağlarında, gradyanların (türevlerin) geriye doğru gidildikçe küçülüp yok olması ve eğitimin durması sorununa ne ad verilir?', 'Exploding Gradient', 'Vanishing Gradient (Kaybolan Gradyan)', 'Overfitting', 'Underfitting', 'B', 'python', 'deep_learning', 'hard', 'Sigmoid gibi fonksiyonlar türevleri 0-1 arasına sıkıştırdığı için, derin ağlarda geriye doğru çarpıldıkça sayılar sıfıra yaklaşır ve öğrenme durur. ReLU bunu çözer.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Zayıf öğrenicileri (genellikle karar ağaçlarını) sırayla ekleyerek ve her yeni ağacın bir öncekinin hatalarını düzeltmesini sağlayarak çalışan güçlü algoritma ailesi nedir?', 'Bagging', 'Boosting (Örn: XGBoost, LightGBM)', 'Clustering', 'Stacking', 'B', 'python', 'ml_algoritmalar', 'hard', 'Boosting algoritmaları (XGBoost gibi), Kaggle yarışmalarında tablosal verilerde en çok kazanan modellerdir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da bir listenin son elemanına ulaşmak için hangi indeks kullanılır?', 'list[0]', 'list[-1]', 'list[last]', 'list[end]', 'B', 'python', 'python', 'easy', 'Python''da negatif indeksleme vardır. -1 son elemanı, -2 sondan ikinci elemanı temsil eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Bir modelin ''Eğitim hatası düşük'' ama ''Test hatası yüksek'' ise bu modelde ne tür bir sorun vardır?', 'Yüksek Bias (High Bias)', 'Yüksek Varyans (High Variance) / Overfitting', 'Düşük Varyans', 'Underfitting', 'B', 'python', 'ml_temel', 'medium', 'Yüksek varyans, modelin eğitim verisine aşırı uyum sağladığını ancak yeni verilerde dağıldığını (genelleme yapamadığını) gösterir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('PyTorch veya TensorFlow''da kullanılan, GPU üzerinde çalışabilen çok boyutlu matrislere genel olarak ne ad verilir?', 'Vector', 'Scalar', 'Tensor', 'DataFrame', 'C', 'python', 'deep_learning', 'easy', 'Tensor, skaler (0D), vektör (1D) ve matrislerin (2D) n-boyutlu genelleştirilmiş halidir ve derin öğrenmenin temel veri yapısıdır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Veri setini Eğitim/Test olarak ayırırken, hedef değişkenin (Sınıfların) oranını her iki parçada da korumak için hangi yöntem kullanılır?', 'Random Split', 'Stratified Sampling (Tabakalı Örnekleme)', 'Sequential Split', 'Batch Split', 'B', 'python', 'ml_temel', 'medium', 'Eğer veride %10 hasta varsa, Stratified Split hem eğitim hem de test setinde %10 hasta olmasını garanti eder.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da bir string, liste veya tuple''ın uzunluğunu (eleman sayısını) veren yerleşik fonksiyon hangisidir?', 'size()', 'count()', 'length()', 'len()', 'D', 'python', 'python', 'easy', '`len([1,2,3])` komutu 3 sonucunu döndürür. Python''un en sık kullanılan fonksiyonlarındandır.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Eğitilmiş bir modeli, yeni veri geldiğinde tekrar en baştan eğitmek yerine, mevcut ağırlıkları koruyarak yeni veriye adapte etme işlemine ne denir?', 'Pre-training', 'Fine-Tuning (İnce Ayar)', 'Zero-shot Learning', 'Encoding', 'B', 'python', 'deep_learning', 'medium', 'Fine-Tuning, genellikle büyük bir modelin (örn: BERT) genel bilgisini alıp spesifik bir görev (örn: tweet analizi) için az miktarda veriyle özelleştirilmesidir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Görüntü işlemede ''Object Detection'' (Nesne Tespiti) ile ''Image Classification'' (Görüntü Sınıflandırma) arasındaki temel fark nedir?', 'Fark yoktur.', 'Sınıflandırma resimde ne olduğunu söyler; Nesne Tespiti ise ne olduğunu ve nerede olduğunu (Bounding Box) söyler.', 'Nesne tespiti sadece videolarda çalışır.', 'Sınıflandırma daha zordur.', 'B', 'python', 'deep_learning', 'easy', 'Sınıflandırma çıktı olarak ''Kedi'' der. Nesne tespiti (örn: YOLO) ise ''Kedi şu koordinatlardaki kutunun içinde'' der.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Hiperparametre optimizasyonu yaparken, belirlenen tüm olası kombinasyonları tek tek deneyen yöntem hangisidir?', 'Random Search', 'Grid Search', 'Bayesian Optimization', 'Manual Search', 'B', 'python', 'ml_temel', 'medium', 'Grid Search, verdiğiniz parametre aralıklarındaki her bir kombinasyonu dener (çok uzun sürer ama garantidir); Random Search ise rastgele seçkiler yapar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Python''da bir metni (string) belirli bir ayıraca göre bölüp listeye dönüştürmek için hangi metot kullanılır?', 'slice()', 'strip()', 'split()', 'divide()', 'C', 'python', 'python', 'easy', '`''a,b,c''.split('','')` komutu `[''a'', ''b'', ''c'']` listesini verir.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Makine öğrenmesi modellerini internet üzerinden başka uygulamaların kullanımına açmak (Deploy) için en sık kullanılan Python kütüphaneleri hangileridir?', 'Matplotlib & Seaborn', 'Flask & FastAPI', 'NumPy & Pandas', 'Keras & PyTorch', 'B', 'python', 'python', 'medium', 'Flask ve FastAPI, ML modelini bir REST API olarak sunarak web sitelerinin veya mobil uygulamaların modelle iletişim kurmasını sağlar.', true, NOW());
INSERT INTO forum_quizquestion (question, option_a, option_b, option_c, option_d, correct_answer, category, topic, difficulty, explanation, is_active, created_at) VALUES ('Görüntü verilerini artırmak (elimizdeki resimleri döndürerek, kırparak, rengini değiştirerek çoğaltmak) ve overfitting''i engellemek için kullanılan tekniğe ne denir?', 'Data Augmentation (Veri Artırma)', 'Data Cleaning', 'Feature Extraction', 'Dimension Reduction', 'A', 'python', 'deep_learning', 'easy', 'Data Augmentation, eldeki veri az olduğunda suni çeşitlilik yaratarak modelin daha kararlı öğrenmesini sağlar.', true, NOW());